quests[11355] = { id = 11355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. What their ultimate destination is, I do not know.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey.\n\nUse this pick to deactivate the runes on the giants' corpses and return with your findings.", sourceObjective = "Researcher Aderan at Fort Wildervar wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", completion = "<Researcher Aderan listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared multiple times? There's a highly reinforced command to move in that direction, but the runes are more than propulsion. Something is attracting them, but what?", sourceObjectiveStatus = "unverified-source-field" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Costumed Orphan Matron", description = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages.  Those poor children would love to see a real {class} like yourself!\n\nWhy don't you visit them?  You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst.  Speak to the children's ward, a costumed orphan matron, and she'll introduce you to the children.", sourceObjective = "Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.", completion = "You're here to visit the children!  Wonderful!  They have known such heartache in their short lives.  It is good that they see real heroes like you.  It really lifts their spirits!", sourceObjectiveStatus = "unverified-source-field" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masked Orphan Matron", description = "For Hallow's End, orc orphans were taken on a trip to many Horde villages.  The orphan matrons thought it would be good for them to see real heroes adventuring in the field.\n\nWhy don't you visit them?  A brave {class} like yourself could strengthen their spirits with tales of your valor!  Go to either Razor Hill in Durotar, Brill in Tirisfal Glades or Falconwing Square in Eversong Woods.  Speak with the masked orphan matron and she'll introduce you to the children.", sourceObjective = "Speak with a Masked Orphan Matron in either Razor Hill, Brill or Falconwing Square.", completion = "The children love to watch heroes at their work.  It is my hope that, one day, each of these orphans will grow into a strong member of the Horde, and ultimately die in glorious battle!\n\nAh, thoughts of such a fine fate brings mist to my eyes...", sourceObjectiveStatus = "unverified-source-field" }
quests[11358] = { id = 11358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lodestone", description = "If we can locate what's luring the giants northwest, we might be able to stop them before they reach their destination.\n\nAlthough I was able to decipher many of the runes on the samples you brought me, the ones I don't know concern me the most. When I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.", sourceObjective = "Researcher Aderan at Fort Wildervar wants you to compare the Rune Sample with the Broken Tablet.", progress = "Have you discovered what lodestone attracts the giants?", completion = "<Aderan listens as you describe your findings.>\n\nOf course! This Megalith must be the key to the Iron Dwarves' plans. We must destroy it before their plan comes to fruition!", sourceObjectiveStatus = "unverified-source-field" }
quests[11359] = { id = 11359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", sourceObjective = "Defeat Megalith and return to Researcher Aderan at Fort Wildervar.", progress = "Do you bring news of Megalith's downfall?", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nI know of no place with that name, but it sounds like a word with origins in the titans. What plans do the Iron Dwarves have for such a thing? This bears watching, {name}, for we must find it before the Iron Dwarves' plan comes to fruition.", sourceObjectiveStatus = "unverified-source-field" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?\n\nNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the north!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The grunts set up a fire training area outside the village.  These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter!\n\nHead west out of Razor Hill, then turn right as you pass the village's wall.  Find the training area, then grab buckets and toss them on the practice fires.", sourceObjective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.", progress = "Have you dowsed any fires, {name}?  The training area is west of Razor Hill's western exit.", completion = "Well done, {name}!  Children, take a good look at this {class}. Grow strong and brave like him and one day you too will fight for the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Keli'dan's Feathered Stave", description = "There is no accounting for taste. Take my most recent buyer for instance.\n\nThere is a blood orc within Hellfire Citadel known as Keli'dan the Breaker. He bears a most mundane stave; certainly nothing to take a second glance at. And yet, this is what my customer wishes.\n\nWho am I to say no?\n\nIf you desire my compensation, you will find him and his stave within the Blood Furnace.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Keli'dan's Feathered Stave. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We are speaking again... you must have the stave.", completion = "Perhaps I will have new feathers tied onto it before shipping it on to the buyer. I'm certain with so many arakkoa hereabouts it will not prove difficult. A small matter, and nothing to detract from your reward in any case.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Bladefist's Seal", description = "Today I have a very wealthy collector in need of something very unique indeed.\n\nWarchief Kargath Bladefist carries upon his person his seal of command, which he uses to sign all official documents. I want you to retrieve it for me.\n\nYou will find him deep within the Shattered Halls. No doubt you will have to wade through a veritable army to get to him. I have no doubt that you will succeed.", sourceObjective = "Wind Trader Zhareem has asked you to obtain Bladefist's Seal. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I have heard it whispered that the warchief has weapons in place of his hands. Is this true?", completion = "Truly a daring acquisition that the bards should put pen to parchment for. Here, you have more than earned this.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Shattered Hand Centurions", description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return until you have slain them all.", sourceObjective = "Nether-Stalker Mah'duun has tasked you with the deaths of 4 Shattered Hand Centurions. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "You have returned. The centurions all lay dead?", completion = "Very well, you have earned your bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11365] = { id = 11365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants.\n\nTake this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you've tested enough giants, return to me with your findings.", sourceObjective = "Sage Edan and Camp Winterhoof wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", progress = "What have you found?", completion = "<The sage listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared over and over? I'm not an expert in these runes, but the repetition of them suggests a strong command.\n\nThese carvings are more than passive directions, though. They seem to pull the giants toward something, but what?", sourceObjectiveStatus = "unverified-source-field" }
quests[11366] = { id = 11366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lodestone", description = "We must find what's luring the giants northwest, so we can stop them before they reach their destination.\n\nWhile the rune samples gave us some clues, the unknown runes worry me.\n\nWhen I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.", sourceObjective = "Sage Edan at Camp Winterhoof wants you to compare the Rune Sample with the Broken Tablet.", progress = "Have you discovered what lodestone attracts the giants?", completion = "<Edan listens as you describe your findings.>\n\nMegalith? A literal transcription from the tablet! This Megalith must be the centerpiece of the iron ones' mysterious plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[11367] = { id = 11367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", sourceObjective = "Defeat Megalith and return to Sage Edan at Camp Winterhoof.", progress = "Do you bring news of Megalith's downfall?", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nIt is not a name our people know, but it sounds like it might be a creation of the \"titans\" the ousiders speak of. The Iron Dwarves have ever been a cunning and dangerous foe, {name}. We must watch these giants and find this Stoneforge before they can carry out their plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Heart of Quagmirran", description = "I have an unusual request. A certain wealthy individual that I am in contact with off-world is interested in a macabre piece.\n\nSpecifically, she wants the heart of Quagmirran.\n\nI hear that the beast has three, but one will suffice for our purposes. As I understand it, you can find Quagmirran resting within a deep pool of water at the Slave Pens.", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Heart of Quagmirran. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I trust that you know of a way to preserve the heart in transit?", completion = "Now that I think of it, it's a pity I didn't ask you to return with the other two hearts as well. Perhaps next time. In any case, you've earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: A Black Stalker Egg", description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction.\n\nIf you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", sourceObjective = "Wind Trader Zhareem wants you to obtain a Black Stalker Egg. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We're speaking again because you have the egg? Outstanding, let me see it!", completion = "Is it not amazing to feel the life pulsing within the egg? I must hurry to deliver it to the purchaser. We wouldn't want it hatching here now would we?\n\nYour payment is ready.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Warlord's Treatise", description = "While it is known that Warlord Kalithresh of the naga is a great warrior in his own right, there are fewer who know that he has codified all of his knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir and obtain this book for me.", sourceObjective = "Wind Trader Zhareem has asked you to acquire The Warlord's Treatise. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "My customer grows restless. I believe he wishes to plumb the depths of the warlord's tactical thinking to help with one of his ongoing conflicts.", completion = "Indeed, I fear my customer will not have time to peruse the entirety of this book. Nevertheless, that is not our concern.  Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Coilfang Myrmidons", description = "Mah'duun hears and obeys, and I now ask you to be my instrument.\n\nIt has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir.\n\nI will accept nothing less than their utter annihilation.", sourceObjective = "Nether-Stalker Mah'duun has asked you to slay 14 Coilfang Myrmidons. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "How fares your fight against the coilfang myrmidons?", completion = "I trust that it was a fight worthy of your time? Certainly this bounty will be.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Headfeathers of Ikiss", description = "I've recently been approached by a tauren whose husband is about to be elevated to chieftain. She wishes to make a special addition to his headdress.\n\nSpecifically, she wants to obtain the headfeathers from the dastardly Talon King Ikiss.\n\nIf you are interested in collecting my reward, travel to Auchindoun's Sethekk Halls and find him.", sourceObjective = "Wind Trader Zhareem has asked you to acquire The Headfeathers of Ikiss. Deliver them to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The time of the chieftain's ceremony grows near.", completion = "I am sure that these feathers will make a fine addition to the chieftain's headdress. You have earned your compensation, {class}.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Shaffar's Wondrous Pendant", description = "Today I have a personal request of you, yet the reward will certainly match the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and his followers. If the amulet he wears were to fall into my hands then surely that would mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you then journey to his lair within Auchindoun's Mana-Tombs.", sourceObjective = "Wind Trader Zhareem wants you to obtain Shaffar's Wondrous Amulet. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Not many know that the source of Shaffar's magic rests solely within his amulet. Without it he is powerless.\n\nThen again, if you have it that must mean that he is dead.", completion = "<You sense a deep level of satisfaction from the wind trader.>\n\nGood, I am glad to hear of his demise. And perhaps I will be able to unlock the secrets of his amulet for myself. If not, then I will sell it for a handsome price.\n\nI trust that this reward is sufficient.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Exarch's Soul Gem", description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken in the pursuit of a greater understanding of the necromantic arts. Many are the spirits that are tortured or destroyed therein.\n\nI have a customer who is interested in the liberation of one of those spirits. I have been informed that this spirit is contained within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out within the crypts with all due haste and return to me with the gem.", sourceObjective = "Wind Trader Zhareem has asked you to recover The Exarch's Soul Gem. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Can you imagine being trapped within a gem for all eternity?", completion = "You're quite the hero, {name}. I am certain that my customer will find a way to free the spirit of their loved one from within the gem. For a job well done, your payment awaits.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Murmur's Whisper", description = "When I'm done speaking, you may not want to take this commission.\n\nI have an eccentric client who specializes in the study of dead realities. It is rumored that the being known as Murmur destroyed the last world from which he was summoned. The professor is interested in examining his 'whisper' as he called it to understand how it is that Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within Auchindoun and retrieve it for me?", sourceObjective = "Wind Trader Zhareem has asked you to obtain Murmur's Whisper. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I'm not even certain what form a whisper is supposed to take in the physical world, but the professor assures me that you'll know it when you see it.\n\nPerhaps it is something akin to the being's voice box?", completion = "I was worried that you might not return. I trust that you didn't go deaf from fighting Murmur?\n\nHere is your reward. The professor will be pleased no doubt, though I worry what he ultimately wishes to do with this thing.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Malicious Instructors", description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf you cannot accomplish so simple a task, we do not have anything further to say to one another.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "The instructors, they are all dead? No?\n\nDid I not say not to return unless you had killed them all?", completion = "I am satisfied. He who speaks through the nether shall be as well. Mah'duun has your bounty prepared.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'deen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge is Tasty", description = "I'm providing the catering for some unusual party guests tonight.  One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly.\n\nThey've requested something special for his get well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of stew for me.  The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Kaliri Stew using his cooking pot. Return to him when it's done.", progress = "Do I smell something tasty?", completion = "Oh, I do smell something tasty!  I hope you gave that bird quite a good beating.\n\nPlease, help yourself to some of my extra stock.  I'm sure someone of your talent could put it to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Epoch Hunter's Head", description = "The tastes of my customers range from the mundane to the exotic. And sometimes they want to do very mundane things with the exotic objects they seek.\n\nSuch is the case with my latest request. My client, who shall remain nameless, wishes to obtain the head of the Epoch Hunter to mount on his wall.\n\n{class}, will you find a way to travel back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?", sourceObjective = "Wind Trader Zhareem has asked you to obtain the Epoch Hunter's Head. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The head of the Epoch Hunter... how does one come to the decision that they want it mounted on their wall?\n\nAnd even then, to not hunt the beast yourself, what does one say to their friends when asked how the fight went?\n\nHe'll lie, I suppose.", completion = "I see you are returned to the present time intact.\n\n<The wind trader looks around.>\n\nIt doesn't appear that anything has changed. But then again, how would I know?\n\nThat's a nice cut; my customer will be pleased. Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Hot Stew", description = "I'm trying to invent something with some real zing.  But to be honest, I'm more of an idea goblin these days.  I've lost my sense of adventure.\n\nBut you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge.  Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Demon Broiled Surprise using his cooking pot, two Mok'Nathal Shortribs and a Crunchy Serpent. Return to him when it's done.", progress = "Any luck with my little experiment?", completion = "Now look at that...\n\n<The Rokk takes a sip of the concoction and his face twists into a bizarre mask of pain and delight.>\n\nSweet A'dal that's good!  A cook with your potential shouldn't be without his proper materials.  Take some of my extra stock and make me proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manalicious", description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are only found in the eco-domes of Netherstorm.  Just don't bother looking around Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", sourceObjective = "The Rokk in Lower City has asked you collect 15 Mana Berries from the Eco-Domes in Netherstorm.", progress = "Any luck, friend?", completion = "Those are the juiciest mana berries I've ever seen.  I think I'm getting smarter just by looking at them.\n\nSince I no longer need most of my meat and fish stock, why don't you take some?  I'm certain you could make something delicious.", sourceObjectiveStatus = "unverified-source-field" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soup for the Soul", description = "Death is in the air.  I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one!  Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking pot, gather some clefthoof meat and I'll let you in on a little secret.  What makes my soup so good for the soul?  It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", sourceObjective = "The Rokk in Lower City has asked you to cook up some Spiritual Soup using his cooking pot. Return to him when it's done.", progress = "What smells so good?", completion = "That is a fine batch of spiritual soup if I ever did smell one.  Just a pinch of pepper and it's done.\n\nAs promised, here's your cut.  And because you did such a fine job, I'm going to throw in some of my extra stock.", sourceObjectiveStatus = "unverified-source-field" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Aeonus's Hourglass", description = "I swear that some of my customers are crazy. There are possessions that you go after, and there are ones that you dare not even think of!\n\nMy current client is clearly over-the-top insane. He covets the hourglass that Aeonus holds.\n\nYes, you heard right, Aeonus of the Infinite Dragonflight!\n\nWho am I to argue since he's paying a king's ransom? So, ready to go to the Caverns of Time and travel to the Black Morass to retrieve it for me?", sourceObjective = "Wind Trader Zhareem has asked you to acquire Aeonus's Hourglass. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "If I were you, I would be very careful with time-travel. You wouldn't want to accidentally do something, like kill one of your ancestors, and then accidentally erase yourself from the present!", completion = "Odd that the sands in that thing are still falling upward. I think I will have it delivered to its new owner with all due haste.\n\nI thank you for a job well done, {class}. You have certainly earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Rift Lords", description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but the voice on the winds was not more specific.\n\nTravel to the Black Morass through the Caverns of Time and the way shall be made clear.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 4 Rift Lords. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "We are speaking, but I sense that all of the rift lords are not yet dead.\n\nReturn again when they are, {class}.", completion = "You found your way back in time, and then back again. You must be a great {class}, {race}. The bounty is earned.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: A Warp Splinter Clipping", description = "Not long ago, I was approached by a kaldorei druidess with a touching request. And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to restore an ancient of the arcane known as Warp Splinter. The giant tree has been confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.", sourceObjective = "Wind Trader Zhareem has asked you to obtain a Warp Splinter Clipping. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Did you lose your way to the Botanica? You can't miss it... it's at Tempest Keep off of the eastern edge of the Netherstorm.", completion = "Aw, you did get it! It's so tiny. And yet, when the druids are done with it -- a process I am told will take a very long time -- Warp Splinter will be regrown anew.\n\nAnd here is your reward as promised.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Sunseeker Channelers", description = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today.\n\nThey are to be found within the Botanica at Tempest Keep.\n\nYou want the bounty, you kill the channelers.", sourceObjective = "Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", progress = "How can it be that we are speaking when the channelers are not all lying dead?", completion = "And now they are dead, channeling no longer. He who whispers upon the nether is satisfied and you have secured the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Pathaleon's Projector", description = "I always assumed that Pathaleon the Calculator used magic to project his image across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood elf uses a mechanical device for his communication with the leaders of Prince Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.", sourceObjective = "Wind Trader Zhareem has asked you to acquire Pathaleon's Projector. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It's not that projector technology is something special in and of itself, but the range of this particular model is a true breakthrough!", completion = "I'm tempted to keep it for myself and return my client's money. It could certainly expand the reach of my business.\n\n<The wind trader sighs.>\n\nHowever, I have a reputation to uphold.\n\nSpeaking of my reputation, thank you for helping me to maintain it. Here is your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Tempest-Forge Destroyers", description = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled.\n\nGo to Tempest Keep, find the tempest-forge destroyers and destroy them.\n\nThen you may return to collect the bounty.", sourceObjective = "Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "Mah'duun enjoys fighting constructs; they are less messy than organic beings.\n\nThe bounty is yours.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Scroll of Skyriss", description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll that contains their instructions for his domination of life in the universe on their behalf.\n\nMy current buyer wishes to get <his/her> hands on that scroll, nevermind that <he/she> won't be able to read the language upon it.\n\nTravel to Tempest Keep's Arcatraz and get it for me, will you, {class}?", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Scroll of Skyriss. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It must be a very dangerous thing to do to meddle directly in the affairs of the Old Gods.\n\nBetter you than me!", completion = "I dare not touch the scroll lest I too risk the notice of the Old Gods. I will have one of my assistants handle its delivery.\n\nYou have more than earned your reward, {class}, and I wish you all the luck in the known worlds.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Arcatraz Sentinels", description = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help.\n\nMah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels.\n\nAccomplish this and today's bounty is yours.", sourceObjective = "Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels. Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.", completion = "With the sentinels destroyed, perhaps the naaru will ask the Consortium to replace them? Mah'duun does not know and does not care.\n\nYou have earned the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11390] = { id = 11390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got a Flying Machine!", description = "Well, what are you waiting for, there's work to be done!\n\nHere's the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I'll mark them for you.\n\nHurry up! We haven't got all day!", sourceObjective = "The Steel Gate Chief Archaeologist wants you to transport 3 Sacks of Relics from the bottom of the site and take them to the platform on the north or south side of Steel Gate.\n\nUse the grappling hook on the flying machine to do this.\n\nReport back to him after you've done so.", completion = "Good job, though I think ye might be wanting a refresher course in basic piloting.\n\nWell, no matter, one warm body's as good as another. Here's yer haul for the day.", sourceObjectiveStatus = "unverified-source-field" }
quests[11391] = { id = 11391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steel Gate Patrol", description = "Eh? Yer back for another day's work?\n\nWell, alright, here's the keys. We don't need any haulin' today, so just keep an eye out for anything suspicious, okay?\n\nI've hooked her up with some rockets and a machine gun - just in case.", sourceObjective = "You're Steel Gate's ace pilot now, so the Steel Gate Chief Archaeologist wants you to keep patrol around the dig site and fight off anything that attacks.\n\nReport back to him when you're done with your patrol.", completion = "Nice shooting, ace.\n\nHere's your wages. Come back tomorrow for another round, ya hear?", sourceObjectiveStatus = "unverified-source-field" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine.", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11393] = { id = 11393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where is Explorer Jaren?", description = "{name}, my betrothed, Jaren, went west with a small group of explorers to check into rumors of artifacts on the Chillmere Coast. But there are murloc down there, and I fear the worst has befallen them.\n\nSurely you have time to see if they're alright? There's a way down to the beach just to the southwest, though watch out for the worgs and other things lurking in the woods.", sourceObjective = "Overseer Irena Stonemantle has asked you to locate her fiance, Explorer Jaren.", completion = "<The explorer beams a smile as you tell him who sent you. He continues in hushed tones.>\n\nIrena was concerned about me?  She gets that from her father you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[11394] = { id = 11394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And You Thought Murlocs Smelled Bad!", description = "Originally I came down here to investigate some rumors about artifacts to be dug up. I knew that there were murlocs along the coast here, but I never in a million years thought I'd see this.\n\n<The explorer pokes his head out to look around the tree.>\n\nThe Scourge are out there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, I think it's our duty to do something about this. Think you could take out a good chunk of those Scourge?", sourceObjective = "Explorer Jaren has asked you to kill 15 Scourge of any type along the Chillmere Coast. Return to him once you have done so.", progress = "I don't know, {class}, it doesn't look like you've destroyed enough of them yet.", completion = "<Jaren seems very excited about your success, but motions you to keep your conversation to a whisper.>\n\nGreat job, {name}! That's a lot of Scourge goo all over your stuff though. You might want to think about a quick dip in the strait. It's cold, but it'll get you cleaned up right quick.", sourceObjectiveStatus = "unverified-source-field" }
quests[11395] = { id = 11395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Explorer Jaren would like to have a look at this.", sourceObjective = "Deliver the Scourge Device to Explorer Jaren on the Chillmere Coast.", progress = "What an odd-looking device you have there, {class}. Let me have a closer look at it.", completion = "I know what this is! {name}, it's a controlling device for those scourging crystals!\n\nI bet anything that it can be used to shut down their force fields. Hmmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11396] = { id = 11396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nWhat do you say, {name}? You up for it? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nIt's the least we can do to keep the Scourge from making more of their own kind.", sourceObjective = "Explorer Jaren on the Chillmere Coast has asked you to destroy 3 Scourging Crystals.", progress = "I don't know, {name}. I think you need to take out a few more of those things.", completion = "Nice!\n\n<Jaren looks around quickly to make sure that nothing noticed his outburst.>\n\nAlright, you certainly earned your pick of one of these things I found while I was down here.\n\nAnd, {name}, if you happen to find yourself back at Steel Gate, give Irena my love and let her know that I'm okay.", sourceObjectiveStatus = "unverified-source-field" }
quests[11397] = { id = 11397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And You Thought Murlocs Smelled Bad!", description = "I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I'd see this!\n\nThe Scourge are down there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!", sourceObjective = "Apothecary Anastasia has asked you to destroy 15 Scourge of any type along the Chillmere Coast. Return to her at the Apothecary Camp once you have done so.", completion = "<Anastasia ponders your success for a moment.>\n\nA satisfactory job to be certain, yet somehow I sense that there's something else we should be doing to stop the efforts of the Scourge on that beach.", sourceObjectiveStatus = "unverified-source-field" }
quests[11398] = { id = 11398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Apothecary Anastasia would like to have a look at this.", sourceObjective = "Deliver the Scourge Device to Apothecary Anastasia at the Apothecary Camp.", progress = "What's that you have there, {class}? Let me have a closer look at it!", completion = "I can tell you what this is, {name}. It's a controlling device for those scourging crystals down there!\n\nI bet anything that it can be used to shut down their force fields. Hmmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11399] = { id = 11399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nBrave enough to hazard another trip down there, {name}? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nHow can you refuse if it means less Scourge, especially ones made from murlocs?", sourceObjective = "Apothecary Anastasia at the Apothecary Camp has asked you to destroy 3 Scourging Crystals.", progress = "You still haven't destroyed enough scourging crystals. No reward until you do so.", completion = "<Anastasia turns and smiles at her succubus.>\n\nVery well, {name}, I concede that you have certainly earned a choice of one of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[11400] = { id = 11400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Pol Amberstill, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", sourceObjective = "Bring the \"Honorary Brewer\" Hand Stamp to Pol Amberstill near the entrance to the Brewfest Grounds in Dun Morogh.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, {name}... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", sourceObjectiveStatus = "unverified-source-field" }
quests[11401] = { id = 11401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11402] = { id = 11402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clayton's Quest: Extreme!!", description = "Clayton wants you to find and slay twenty Evil Squirrels.", sourceObjective = "Seriously, go slay those Evil Squirrels!", sourceObjectiveStatus = "unverified-source-field" }
quests[11403] = { id = 11403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", sourceObjective = "Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.", progress = "{name}, it is good to see you again.  I'm sure the children enjoy tales of your heroism.", completion = "What?  This holy tome once belonged to an infamous paladin of the Alliance.  Was he the Headless Horseman?  Does this mean that the Horseman is defeated?\n\nThis is a glorious day, {name}!  Your legend will shine bright, and may it last for twice the years of the Horseman's reign of fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11404] = { id = 11404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11405] = { id = 11405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", sourceObjective = "Take a Dreary Candle to the Loosely Turned Soil.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", sourceObjectiveStatus = "unverified-source-field" }
quests[11406] = { id = 11406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Must Be Ready", description = "When the expeditionary force moves north, Captain Adams expects everything to be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with preparing the gear and rations for our men for the climb into the hills.\n\nThe captain's famous for his temper, so I want to send someone ahead to check on the preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make sure he is prepared.", sourceObjective = "Speak with Gil Grisert at Fort Wildervar.", completion = "So the quartermaster sent you?\n\n<Gil seems relieved.>\n\nTo be honest, we're running a bit behind here and we're going to need some help making our goals.\n\n<Gil shudders.>\n\nNone of the men want to brave the wrath of Captain Adams.", sourceObjectiveStatus = "unverified-source-field" }
quests[11407] = { id = 11407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for Drohn's Distillery!", description = "So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nWe'll lend you a racing ram for 4 minutes.\n\nBe careful though, the cheap goblins didn't put any apple crates along the way.", sourceObjective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?", completion = "You kept your word and let people know about our brewmasters.  Thank you. We promised you these tokens, and gladly give them to you.  I imagine the trolls are a bit more stingy with handing over their tokens...\n\nCome back another day to help us spread the word about Brewfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[11408] = { id = 11408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for T'chali's Voodoo Brewery!", description = "We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.\n\nBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.", sourceObjective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the amazing troll brew?", completion = "Ya did it!  We gotta get ready for the flood of customers that are sure to come our way!  Thanks!\n\nOh, that's right, and we promised you a reward.  Can't forget about that...\n\nFeel free to stop by again another day to help us spread the word some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11409] = { id = 11409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", sourceObjective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", completion = "Hey, that wasn't too bad... are you sure you're not a dwarf?\n\nSo there's plenty more racing to be had and it's not just from me.  All over the Brewfest grounds you'll find people in need of a decent ram racer.  So go and make yourself useful.\n\nOh and don't forget, these rams were legally obtained.  I just want to make sure we're clear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11410] = { id = 11410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The One That Got Away", description = "The barbfish you brought should work well as bait for most fish, but I fear it'll attract a monster!\n\nWhen I first arrived, I put some of Nat Pagle's favorite bait on my hook and cast it into the water. A huge monster latched on, with giant teeth and icicles hanging from its fins!\n\nWould've pulled me into those icy waters if I hadn't cut the line! I can't use the new bait until ol' Frostfin's been dealt with. Use this bait near the sunken boat in the middle of the lake. He won't be able to resist!", sourceObjective = "Christopher Sloan at Fort Wildervar wants you to defeat Frostfin.", progress = "I'm itching to try out the new bait.\n\nHave you had any luck with Frostfin?", completion = "At last, we can finally fish in peace! 'Course, by the time we catch anything, the expedition'll arrive and claim it all for themselves.\n\nYou have our thanks, {name}. Don't be a stranger 'round here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11411] = { id = 11411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Winterhoof", description = "In my travels as a courier, I've seen a number of strange denizens of the Howling Fjord, but one group stands out. From a distance, they look like tauren, but upon closer inspection, they're quite different -- sturdier and shaggier.\n\nI found one of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border with Grizzly Hills. Make contact with them, and see if they might be of use to us.", sourceObjective = "Speak to Chieftain Ashtotem at Camp Winterhoof.", sourceObjectiveStatus = "unverified-source-field" }
quests[11412] = { id = 11412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There and Back Again", description = "Am I glad you're here.  We are in big trouble!  The goblin that was supposed to be bringing us more brew had an accident on his way from Bladefist Bay.  You gotta get us that brew!\n\nI'll put you on one of my racing rams and you follow the road to Bladefist Bay.\n\nOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant.  For now, all we want are 3 kegs.  Do a good job and maybe we'll have another job for you.", sourceObjective = "Get a keg from the goblin stranded on the road to Bladefist Bay and return it to Ram Master Ray's assistant. If you lose your ram, ask Ram Master Ray for another.", progress = "Did you see the mess that goblin made?  I hope you didn't do too much reckless off-roading.", completion = "Thanks for your help!  As long as Brewfest is going, the Dark Iron dwarves are attacking and our supplier is stuck in that canyon, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nHere are the tokens we promised you.  Have fun!", sourceObjectiveStatus = "unverified-source-field" }
quests[11413] = { id = 11413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", sourceObjective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[11414] = { id = 11414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Betrayers", description = "Watcher Moonleaf is from my dreams! If you are her friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha worg. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", sourceObjective = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11415] = { id = 11415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Betrayers", description = "Mistwalker is from my dreams! If you are his friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", sourceObjective = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11416] = { id = 11416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", sourceObjective = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!", sourceObjectiveStatus = "unverified-source-field" }
quests[11417] = { id = 11417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", sourceObjective = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!", sourceObjectiveStatus = "unverified-source-field" }
quests[11418] = { id = 11418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Call Him Steelfeather", description = "We see one brave hippogryph circling over the fort, then swooping down and taking prey. Jethan over there has taken a couple of shots at the creature, but his arrows bounced right off!\n\nWe've taken to calling this remarkable creature Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most hippogryphs are wary of people.\n\nResearcher Aderan has helped us fashion a charm from one of the creature's feathers. He claims it will allow the user to see through Steelfeather's eyes.", sourceObjective = "Locate Steelfeather circling Fort Wildervar and use the Feathered Charm to discover his secret. Report your findings to Gil Grisert.", progress = "Did Aderan's charm work?", completion = "You saw a nest, with hatchlings? Hmm... so our \"he\" is actually a \"she,\" eh?\n\nI guess that settles it. I suppose I wouldn't want to move a nest full of hatchlings just because of a new neighbor, either.\n\n<Gil favors Trapper Jethan with a mock glare.>\n\nI'm sure we'd get along just fine if ol' Jethan would stop trying to make a trophy of her.", sourceObjectiveStatus = "unverified-source-field" }
quests[11419] = { id = 11419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", sourceObjective = "Bring the \"Honorary Brewer\" Hand Stamp to Driz Tumblequick near the entrance to the Brewfest Grounds in Durotar.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, {name}... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", sourceObjectiveStatus = "unverified-source-field" }
quests[11420] = { id = 11420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Payback", description = "Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual.\n\nUnfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!", sourceObjective = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to recover the Harpoon Operation Manual.", progress = "Did you find the manual?", completion = "<Zorek flips through the manual.>\n\nHrm, interesting...\n\nAccording to the manual, the vrykul have a special tool that allows them to control the harpoon guns with deadly accuracy. It looks a bit like the wheel of one of our ships. Furthermore, it's portable and seems to plug into the harpoon guns like a key. We need to get our hands on one of those!", sourceObjectiveStatus = "unverified-source-field" }
quests[11421] = { id = 11421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Goes to 11...", description = "We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village.\n\nOnce there, commandeer one of the vrykul harpoon guns that are stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you!\n\nDo this and Daggercap Bay will become a much safer port!", sourceObjective = "Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders.\n\nReturn the Harpoon Control Mechanism to him once the task is complete.", progress = "Is Wyrmskull up in flames?", completion = "Excellent work, {name}! You took out a good chunk of their dragon riders and really pissed off their leadership.\n\nAre you ready to head back to Valgarde and report the good news to Zorek? If so, I've got a crazy idea!", sourceObjectiveStatus = "unverified-source-field" }
quests[11422] = { id = 11422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trident of the Son", description = "<From the scratches he makes in the rock, you see several symbols: a trident, a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.>\n\n<Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.>\n\n<His son was changed into a mur'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>", sourceObjective = "Old Icefin wants you to obtain Rotgill's Trident. Return it to him on the small island on the Chillmere Coast.", progress = "<One of Old Icefin's dead fish-like eyes studies you, clearly looking for signs of his son's trident.>", completion = "<Reaching out to take his son's trident from you, Old Icefin's hand shakes a little. Could it be that the aged murloc is grieving?>\n\n<Is that just extra moisture pooling at the base of his eye?>", sourceObjectiveStatus = "unverified-source-field" }
quests[11423] = { id = 11423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy's Legacy", description = "As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost.\n\nThis worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val'kyr.  Obtain them before Nifflevar is destroyed.", sourceObjective = "Go into Nifflevar, north of Ghostblade Post and look for the Saga of the Winter Curse, the Saga of the Val'kyr and the Saga of the Twins.", progress = "The scrolls, {name}?  Did you obtain them?", completion = "This is of tremendous value, {name}.  I must renew my efforts in salvaging and translating vrykul texts.\n\nDon't get me wrong.  Our enemies need to be destroyed... their ancient knowledge doesn't.", sourceObjectiveStatus = "unverified-source-field" }
quests[11424] = { id = 11424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shield Hill", description = "My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere.\n\nIt's not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated.\n\nThere is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King's.  Get me some bones, I'll pay ya well.", sourceObjective = "\"Hacksaw\" Jenny wants you to bring her 5 Ancient Vrykul Bones from the reanimated Vrykul in Shield Hill, south of New Agamand.", progress = "Got my bones then?", completion = "Hmmmmph... these will do for now.  There seems to be some oddness to them.\n\nI tell ya - I've handled body parts for years now and never have I had such a weird feeling in my stomach.  Anyway, a deal is a deal.  Here's your payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[11426] = { id = 11426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locating the Mechanism", description = "Don't worry, {name}; this is all going to lead to something big! HUGE! You're just going to have to trust me for now and do as I ask of you.\n\nWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you'll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You'll find them on the east side of the village, on the docks by the longhouses.", sourceObjective = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to bring him a Harpoon Control Mechanism.", progress = "Did you locate the mechanism?", completion = "Outstanding! Those overgrown apes will soon know what it means to mess with the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11427] = { id = 11427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Lieutenant Icehammer...", description = "Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It's where most of their harpoon attacks on our frigates originate.\n\nWell guess what? The time for payback has come, {name}. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.\n\nWhen you're ready I'll place you on the back of one of our gryphons and zip you right to him!", sourceObjective = "Guard Captain Zorek wants you to take the Harpoon Control Mechanism to Lieutenant Icehammer stationed outside of Nifflevar.", progress = "What is this? Do I look like a babysitter?", completion = "<Lieutenant Icehammer takes the harpoon control mechanism from you.>\n\nAh, you come bearing gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[11428] = { id = 11428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper Witherleaf", description = "You have been a great friend and ally to us, {name}. There is one more thing I must ask of you.\n\nYou have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them.\n\nThe most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, {name}, and open the way for the redemption of the glade as you once redeemed my sisters.", sourceObjective = "Lurielle at the Frozen Glade wants you to kill Keeper Witherleaf.", progress = "Have you rid the Twisted Glade of Keeper Witherleaf?", completion = "My heart broke when I learned the keepers had turned against us. Once, we considered them our brothers and our closest friends.\n\nI grieve for the brothers and sisters we have lost, but without your help, there would be no hope for our future. You will always be welcome among us, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11429] = { id = 11429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drop It then Rock It!", description = "I'm not about to put the fate of this mission into the hands of some untested scrub.\n\nNow, if you want to prove to me that you've got what it takes to carry out this mission, you'll need to do what I tell you.\n\nTake this battle standard and head over to Baleheim, directly north of here. Once you're at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you've established Alliance dominance!", sourceObjective = "Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers.\n\nReturn to Lieutenant Icehammer with the Alliance Banner should you survive.", progress = "Still alive, I see. Clearly you're not trying hard enough.", completion = "For the Alliance! You're a strong one, {name}. Strong enough to crack some vrykul skull at Nifflevar.", sourceObjectiveStatus = "unverified-source-field" }
quests[11430] = { id = 11430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpoon Master Yavus", description = "That was a fairly strong showing at Baleheim, {name}. Before you go off patting yourself on the back there's work to be done at Nifflevar.\n\nWe've located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here.\n\nTrack him down and execute him for crimes against the Alliance!\n\nDo me proud, {name}!", sourceObjective = "Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar.", progress = "Have you taken care of Yavus?", completion = "It'll take them a while to find a replacement for Yavus. Now is the perfect time to unleash Zorek's plan! While they're scurrying to regain control of Nifflevar, you're going to use their own harpoon guns against them!", sourceObjectiveStatus = "unverified-source-field" }
quests[11431] = { id = 11431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch the Wild Wolpertinger!", description = "Hey there! I'm a crazy dwarf! We dwarves believe when you get enough brew together, invisible creatures show up. In fact, they are probably wandering around the Brewfest grounds right now! But you can only see them if you are wearing Synthebrew Goggles.\n\nThere might be some other way to see them, but who knows?!\n\nSo here it is, bring me 5 of those wolpertingers with this net I got from a really drunk dwarf.\n\nIf you can't see them, talk to me and I'll give you some Synthebrew Goggles.", sourceObjective = "The \"dwarf,\" Glodrak Huntsniper, has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be wearing Synthebrew Goggles to see them.", progress = "Do you have something for me or are you just looking for another reason to get drunk?", completion = "What!  They really exist!   Now I feel bad for kicking that dwarf in the knee...\n\nI need a minute... and a drink...\n\n<He takes a drink from his stein.>\n\nI guess I could let you keep one... Proof that drunk dwarves (are there any other kind?) actually tell the truth.", sourceObjectiveStatus = "unverified-source-field" }
quests[11432] = { id = 11432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Giants", description = "I've overheard what you've had to say with Father Levariol. Allow me to suggest that he's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", sourceObjective = "Mage-Lieutenant Malister has tasked you with slaying 5 Dormant Vrykul. Return to him at Westguard Keep when you have done so.", completion = "You did what had to be done. Though some might consider it dishonorable to slay the helpless, in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11433] = { id = 11433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Giants", description = "I've overheard what you've had to say with Greatmother Ankha. With all due respect, she's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", sourceObjective = "Ahota Whitefrost has tasked you with slaying 5 Dormant Vrykul. Return to him at Camp Winterhoof when you have done so.", completion = "You did what had to be done. The unwise might consider it dishonorable to slay the helpless while they awaken, but in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11434] = { id = 11434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Treasure", description = "I've made my fortune by specializing in treasure that regular pirates don't appreciate: art, antiquities, collector's pieces.\n\nBlack Conrad's fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine.\n\nGo and retrieve them for me and I'll vouch for you with the other pirates.  I'll even throw in something to make your underwater adventure a bit more manageable.", sourceObjective = "Handsome Terry at Scalawag Point wants you to bring him 1 Amani Vase and 1 Eagle Figurine from the shipwreck to the south.", progress = "Did you obtain my relics, {name}?  Nobody gets by in this life on good looks alone... not even me!", completion = "We're going to go places together, {name}.  With my good looks and your... can-do attitude, we're sure to make a killing.", sourceObjectiveStatus = "unverified-source-field" }
quests[11436] = { id = 11436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Go Surfing Now", description = "Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's harpoon controller! Of course it hasn't been tested, but that's what you're here for!\n\nTake the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.", sourceObjective = "Use the large Vrykul Harpoon Gun in Nifflevar to launch yourself into Valgarde. Report your victory over the Vrykul to Guard Captain Zorek.", progress = "<Zorek raises an eyebrow at you.>", completion = "You are insane, {name}! What kind of degenerate would actually launch themselves from a harpoon gun as a method of travel?\n\nBut I guess you need to be a little crazy to pull off what you did up there on the bluffs! Fantastic work! We've gotten word that the Dragonflayer leader, Ingvar, is furious! Maybe one day you'll be ready to stomp his face into the dirt - in the name of our beloved Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11439] = { id = 11439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?\n\nSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the south!", completion = "You're smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11440] = { id = 11440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?\n\nWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", sourceObjective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the west!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11441] = { id = 11441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", sourceObjective = "Speak to the Brewfest Organizer.", completion = "Ho ho! Come for your free beer?", sourceObjectiveStatus = "unverified-source-field" }
quests[11442] = { id = 11442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "Ho ho! Come for your free beer?" }
quests[11443] = { id = 11443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggercap Divin'", description = "Hey... Uh... What's up? What are you doing down here?\n\nMe? Oh... Well, you see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He says to me, \"Harry, I want you to put on a divin' bell and search the shipwrecks of Daggercap for OUR stuff...\"\n\nSay, maybe you could lend me a hand while you're down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don't run out of air and die.", sourceObjective = "Harold Lagras at the bottom of Daggercap Bay wants you to recover 10 Valgarde Supply Crates.", progress = "Did you find those supplies?", completion = "Wow! You sure are efficient. Yep, well, just give me those crates. I'll need to document them and take inventory and some other stuff that you haven't been trained to deal with or understand. Don't worry; I'll be sure to let Keller know what a great job you did down here! Yep. Yea, you can leave now. Skedaddle!", sourceObjectiveStatus = "unverified-source-field" }
quests[11446] = { id = 11446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Orgrimmar and receive a free beer.", sourceObjective = "Speak to the Brewfest Organizer.", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year.", sourceObjectiveStatus = "unverified-source-field" }
quests[11447] = { id = 11447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year." }
quests[11448] = { id = 11448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers' League Outpost", description = "It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads or tails of these tablets. Admittedly, cryptography is not my strong point.\n\nYou'll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.", sourceObjective = "Deliver McSorf's Bundle to Stanwad at the Explorers' League Outpost in Howling Fjord.", progress = "<Stanwad grumbles.>", completion = "<Stanwad takes the bundle from you and begins sorting the data.>\n\nWow. How many people did you say died to get this information?\n\n<Stanwad shakes his head.>\n\nYou'll be happy to know that what McSorf and his crew of bumbling imbeciles discovered is an ancient recipe for tundra stew. Did he not notice the icons of common vegetables and the pictograph of a humanoid mouth chompin' down on said veggies? You don't need a damned cipher to break this code!", sourceObjectiveStatus = "unverified-source-field" }
quests[11449] = { id = 11449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.\n\nHead west past the graveyard, following the road. You'll find the training area there.", sourceObjective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.", progress = "Have you dowsed any fires, {name}?  The training area is west of Brill.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a strong example to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11450] = { id = 11450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.\n\nHead south through the gate to the crossroads. You'll find the training area there.", sourceObjective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a fine example for you to follow.", sourceObjectiveStatus = "unverified-source-field" }
quests[11451] = { id = 11451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alicia's Poem", description = "Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?\n\nCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!", sourceObjective = "You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland.", progress = "Oh, is that a poem?", completion = "What a touching poem, thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11452] = { id = 11452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", sourceObjective = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Westguard Keep and report your success to Captain Adams.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11453] = { id = 11453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", sourceObjective = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Camp Winterhoof and report your success to Chieftain Ashtotem.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11454] = { id = 11454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Saboteurs", description = "This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.", sourceObjective = "Find Coren Direbrew in the Grim Guzzler within Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[11455] = { id = 11455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fragrance of Money", description = "Us pirates are known for many things, but hygiene isn't one of them.  Most pirate ships be carrying five or six times as many rats as people.\n\nIt's no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants 'em all dead.\n\nIt just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?", sourceObjective = "Handsome Terry at Scalawag Point in Howling Fjord wants you to obtain 4 Bear Musk from the Rabid Brown Bears in the surrounding area.", progress = "Ye got the bear musk for me, matey?", completion = "Excellent work!  It might not be quite as daring as plundering the high seas, but I'd be a darned son of a deckswabber if I passed on this opportunity.", sourceObjectiveStatus = "unverified-source-field" }
quests[11456] = { id = 11456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Survivors", description = "We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals.\n\nThe nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in.\n\nOur catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful.\n\nAid my people by hunting these great beasts and obtaining their meat.", sourceObjective = "Elder Atuik at Kamagua in Howling Fjord wants you to obtain 6 pieces of Island Shoveltusk Meat from Island Shoveltusk in the Isle of Spears.", progress = "Have you obtained the meat we need?", completion = "I thank you, {name}.  My people are in a time of great need.", sourceObjectiveStatus = "unverified-source-field" }
quests[11457] = { id = 11457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming Kamagua", description = "Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young.\n\nIt is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.", sourceObjective = "Elder Atuik wants you to obtain 3 Chimaera Horns.", progress = "It's good to see you again, {race}.", completion = "You continue to prove your worth as an ally, {name}.  Your actions will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11458] = { id = 11458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Iskaal", description = "The totem of Issliruk is ready, {name}, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who've attacked our land and our kin.\n\nThe pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.", sourceObjective = "Elder Atuik wants you to go to Iskaal and slay 8 Northsea Slavers. Use the Horn of Kamagua should you need assistance.", progress = "Have you done what I asked of you, {name}?", completion = "You are a formidable ally, {name}.  My people will forever be in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11459] = { id = 11459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeh'gehn Sez", description = "Is like dis, mon.  Ye be wantin' me 'elp spotting some craven bag-o-wire been cardin' da crew?\n\nYe gotta bring me a croaker, matey.  Aft I an' I show ye who da blaggard be, mon.  Nah, nah, croaker show ye.  Ye'll ku fer yerself with yer own deadlights, yahso.\n\nBring us a carver yahso too, 'atsteppa.  Galang, bucko.", sourceObjective = "Return to Handsome Terry to decipher what Zeh'gehn asked of you.", completion = "You didn't understand a thing Zeh'gehn said?  Well, of course not.\n\nLet's see then.", sourceObjectiveStatus = "unverified-source-field" }
quests[11460] = { id = 11460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trust is Earned", description = "The first and most important factor in falconry is the bond between the falconer and <his/her> bird. Trust must be earned by the master!\n\n<Hidalgo points to the falcons in the cage at his feet.>\n\nIf you are to earn their trust you will first need to fill their bellies.\n\nThe fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to find a Fjord Grub and feed it to one of the falcons in the cage by his feet.", progress = "This is an important exercise, {name}. If you are to become a falconer you must learn how to feed your bird.", completion = "Yes, {name}. I can see the bond of companionship forming. She has accepted you as master.", sourceObjectiveStatus = "unverified-source-field" }
quests[11462] = { id = 11462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handsome Terry", description = "Your people paid me good money to infiltrate the Northsea Freebooters and get your foot in the door.\n\nI talked you up to a fellow in Scalawag Point called Handsome Terry.  I told him you come highly recommended.\n\nPut your disguise on and go see him.  Here comes someone to take you there.\n\nYou're going to have to prove yourself a bit before they introduce you to their higher ups.  But that's all up to you.  Remember, {name}, once you're inside you're on your own!", sourceObjective = "Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[11463] = { id = 11463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirates of the North Seas", description = "The past few weeks have seen an increase in pirate attacks against our supply ships.  We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef.  We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, {name}.  If you take on this task, we can keep our military focused against Arthas' forces.  Are you up to it?", sourceObjective = "Find Grezzix Spindlesnap on the northern end of Garvan's Reef off of the Southwestern coast of Howling Fjord.The past few weeks have seen an increase in pirate attacks against our supply ships. We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef. We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, {name}. If you take on this task, we can keep our military focused against Arthas' forces. Are you up to it?", sourceObjectiveStatus = "unverified-source-field" }
quests[11464] = { id = 11464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gambling Debt", description = "I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts.\n\nSee, pirates love to gamble.  They, however, do not love to pay their gambling debt.\n\nIf you're interested in collecting some coin on my behalf, I'd be willing to give you a cut.\n\nLet's start you out with an easy one.  \"Silvermoon\" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.", sourceObjective = "Taruk at Scalawag Point wants you to collect \"Silvermoon\" Harry's Debt.", progress = "You're back.  Did you get what's owed to me?", completion = "A job well done.  Here's your cut, {name}.  There's more where this came from.\n\nThere's no shortage of deadbeat pirates on this island.", sourceObjectiveStatus = "unverified-source-field" }
quests[11465] = { id = 11465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ransacked Caravan", description = "I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon.\n\n<Hidalgo hands you a cage.>\n\nTake this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you've gathered enough.\n\nRemember to feed the falcon!", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use the Trained Rock Falcon to recover 5 Fjord Turkeys.\n\nReturn to Hidalgo with the cage once you have completed this task.", progress = "Your falcon must be constantly fed or else it will eat the prey that you are sending it to kill.", completion = "Clever fiends. And patient too! We need to stop underestimating our enemy. Those vrykul are deadly hunters!\n\nRegardless, mission accomplished. Perhaps it is time for you to hunt something a bit more elusive than a fat turkey, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[11466] = { id = 11466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack Likes His Drink", description = "Our next customer,  Jack Adams, won't be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let's not use force this time, could get ugly.\n\nSee if you can use his drinking habit to your advantage.  There's only so much alcohol someone can handle before passing out.\n\nMaybe one of the bar wenches will be of assistance.  Once he's out, see if you can slip your hand into his pocket and get what's mine.", sourceObjective = "Taruk at Scalawag Point in Howling Fjord wants you to collect Jack Adams' Debt.", progress = "Did you get what's mine, {name}?", completion = "I'm impressed, {name}.  And I'm not the type who's easily impressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[11467] = { id = 11467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Man's Debt", description = "You might've heard of Black Conrad, he's a famous pirate around these parts.\n\nWell, he had a thing for gambling on my fights.  He had a thing for not paying, too.\n\nI'd love to collect, but trouble is... he's dead.\n\nI was about ready to write the whole thing off, when I came across this...\n\n<Taruk unfolds a map of the Isle of Spears with an X on a northeastern plateau.>\n\nHe hid his treasure on tuskarr land.  I want you to get it.  I'll be damned if I let that bilge sucker get away without paying.", sourceObjective = "Taruk at Scalawag Point wants you to search for Black Conrad's Treasure on the plateau in the northeastern end of the Isle of Spears, just north of Iskaal.", progress = "Did you find the treasure, {name}?", completion = "I'll take the gold, as it is what Conrad owed me.  The rest is for you to keep.\n\nIf you're ever in need of something more permanent, I'm sure I could arrange for something.  In the meantime, may the wind blow strong in your sail, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11468] = { id = 11468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falcon Versus Hawk", description = "Do you feel the closeness, {name}? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you'll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry.\n\nBut first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 10 Fjord Hawks.\n\nReturn to Hidalgo with the cage when you have completed this task.", progress = "Your falcon must be constantly fed or else it will eat the prey you are sending it to kill.", completion = "Aye, the hawks are very territorial and often travel in packs. I suppose I could have told you that before I sent you out into the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[11469] = { id = 11469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swabbin' Soap", description = "Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes 'round. An' I ain't gonna do it on my hands and knees neither!\n\nProblem is, we're all outa soap. That's more your problem than mine though, mate. Being the newbie 'round here, I gots a special trip for ya to make.\n\nUp on the northwest coast of this island, there's a whole mess o' sea lions. Amongst the nearby ice floes you'll find the alpha bull, Big Roy. Bring me back his blubber and I'll magic-up the best soap ya ever seen!", sourceObjective = "Scuttle Frostprow wants you to obtain Big Roy's Blubber as the main ingredient for her magic swabbin' soap. Return to her on the eastern pirate ship at Scalawag Point when you have it.", progress = "Where's that blubber? An' don't try to tell me he ain't got none either.\n\nThat Big Roy's so damned big it's a wonder he can still galumph around!", completion = "Ew, that's a stink if I ever smelled one!\n\nGo on now, put it down right here. I'll cast my spell and she'll be swabbin' soap for sure!", sourceObjectiveStatus = "unverified-source-field" }
quests[11470] = { id = 11470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Exists No Honor Among Birds", description = "You are most definitely ready for the next step in falconry, {name}.\n\nTake your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From the roost you will send out your falcon to steal the eggs of the hawks. Their nests will be located in remote areas of the cliff walls surrounding the roost. Locate those nests and use your falcon to scavenge for the eggs!\n\nBeware the fjord hawk matriarchs, {name}. Should you come under attack, use your falcon's escape and soar abilities to flee!", sourceObjective = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 8 Fjord Hawk Eggs.\n\nReturn to Hidalgo with the cage when you have completed this task.", progress = "You are in control now, {name}. Guide your falcon and bring me those eggs.", completion = "Bravo, {name}! Bravo! The bond of kinship between you and your falcon is strong! Perhaps you can run some reconnaissance missions against the vrykul in the not-too-distant future?", sourceObjectiveStatus = "unverified-source-field" }
quests[11471] = { id = 11471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jig is Up", description = "I know why you're here, {name}.  You've been sent to kill our leader, Jonah Sterling.\n\nI'd like to offer my help.  Jonah's leadership threatens our operation.\n\nAttacking the Horde and the Alliance fleets simultaneously?  Suicidal.  Trying to sell the tuskarr as slaves when they die days after leaving this climate?  Disastrous.\n\nJonah's hideout is located inside a cave west of here.  Bring me his spyglass as proof of the deed and my first action as leader will be to end all attacks against your allies.", sourceObjective = "Annie Bonn at Scalawag Point wants you to bring her Jonah Sterling's Spyglass.", progress = "Well, {name}.  Did you get Jonah's spyglass?\n\nI can't just take your word for the assassination, you know?  I am a pirate after all.", completion = "Jonah Sterling's days are finally over!  He never thought this \"wench\" would make it.\n\nAs word of Jonah's death spreads among the pirates I will consolidate my leadership.  Your allies won't get any more trouble from my crew, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11472] = { id = 11472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way to His Heart...", description = "The Northsea Pirates slaughtered the isles' alpha sea lion bull, Big Roy. They made soap from him to clean the decks of their ships!\n\n<Anuniaq sighs.>\n\nNow the sea lions won't mate. Help me to repopulate their numbers.\n\nThe reef bulls can be found at the Twin Shores to the southeast. They crave the tasty reef fish that can be found on the east and west sides of the isles.\n\nTake this net and gather enough fish, at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.", sourceObjective = "Toss Tasty Reef Fish at a Reef Bull to lead it to a Reef Cow. Once you have helped the two to find true love, return to Anuniaq at Kamagua.", progress = "Have you helped a reef bull and cow to get to know each other?", completion = "This is good news! Now more bulls will swim across the strait to mate with the cows. Soon there will be plenty of new reef pups on the isles.\n\nThank you, {race}. Whatever you might have done in the past, know that you have helped with Kamagua's future!\n\nWe'll have to keep up the good work if we're going to see to it that their numbers are replenished. Please come back again tomorrow so that we can help another couple find each other.", sourceObjectiveStatus = "unverified-source-field" }
quests[11473] = { id = 11473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Traitor Among Us", description = "Our second in command, Annie Bonn, has been acting rather paranoid as of late.  She seems sure we have an infiltrator in our ranks, can ye believe it?\n\nAnyhow, we have a foolproof way of uncovering rats around these parts.  See, good ole' Zeh'gehn over here happens to be an authentic witch doctor.  His family hails all the way from Zul... something or other.\n\nGo let him know that we're in need of his divination skills.  I must warn ye, {name}, only one or two of us can understand anything Zeh'gehn says.", sourceObjective = "Speak to Zeh'gehn at Scalawag Post.", completion = "Ku here, mate.  Ye come fe see I an' I, aye?", sourceObjectiveStatus = "unverified-source-field" }
quests[11474] = { id = 11474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Problems on the High Bluff", description = "As usual, the real work is left up to me and my crew. Thankfully McSorf's team didn't die for nothin'. The cipher they recovered will help us crack the stuff we've found up here - that is if we can ever get back to it! Damned iron dwarves have sprung up like leaks all over the place and are now attemptin' to bury the sites! Can you believe it? Bastards want to bury our finds!\n\nAnyhow, talk to Walt over yonder. He'll get you started.", sourceObjective = "Speak with Walt.", completion = "Over half our team is dead or missing, junior. This is our last stand up here on the high bluffs. Those damned iron dwarves pushed us out of both Ivald's Ruin and Baelgun's. Now I've got a plan to get us back inside before they bury up all our goodies and we lose that data forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[11475] = { id = 11475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools to Get the Job Done", description = "I've been studying this deactivated construct for days, {name}. I think I can create a reasonable facsimile of the golem that would have room inside to fit one passenger. The idea being that it would fool those iron dwarves and allow us to get inside Baelgun's.\n\nNow I'm not gonna be able to make anything with a hammer and poker. I need my tools! Unfortunately I left those behind at Ivald's Ruin when the iron dwarves first attacked. Get me my tools!\n\nIvald's Ruin is located far to the northeast.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to recover his Building Tools.", progress = "Step 1: Get Walt his tools.", completion = "Now that I've got my tools, the building can begin. Well, as soon as I have some materials. You'll be getting those for me next.", sourceObjectiveStatus = "unverified-source-field" }
quests[11476] = { id = 11476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Carver and a Croaker", description = "Some of the pirates around here... we have our own special way of talking.  Zeh'gehn has... many different special ways of talking... all mixed together.\n\nFrom what I can tell he wants a frog and a knife.\n\n\"Silvermoon\" Harry might have a knife on the cheap.  There's frogs all over town, just grab one and bring it to him along with the knife.\n\nI'd hate to be in the poor critter's shoes, if you know what I mean.", sourceObjective = "Get a Shiny Knife from \"Silvermoon\" Harry and capture a Scalawag Frog. Bring these to Zeh'Gehn at Scalawag Point.", progress = "Ye get the croaker and carver, mon?", completion = "Much obliged, bucko.  Croaker's lookin' real cris!", sourceObjectiveStatus = "unverified-source-field" }
quests[11477] = { id = 11477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of My Element?", description = "Keep it down, {race}. These iron dwarves are quick on the trigger. Now don't let the activities down in the dig fool you. Those steel-skinned abominations aren't digging anything up! No sir - on the contrary - they're burying the site! For whatever whacked out reason, they don't want anyone finding this place.\n\nWhat kind of dwarf buries ancient relics and dig sites? I'll tell you what kind: the kind you kill with reckless abandon! Get in there and take 'em out!", sourceObjective = "Donny at Ivald's Ruin in the Howling Fjord wants you to kill 10 Iron Rune Destroyers, 5 Iron Rune Laborers and 2 Iron Rune Sages.", progress = "You'll need to kill until you've had your fill.", completion = "Good job, {name}. That'll slow down the burial process a little.", sourceObjectiveStatus = "unverified-source-field" }
quests[11478] = { id = 11478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outpost Over Yonder...", description = "I see that you haven't visited my brothers at the Explorers' League Outpost south of here. Why don't you do Donny a favor and deliver this message to Stanwad. He'll be interested to hear about the activities of the iron dwarves up here.\n\nLike I said, mount up and start heading south. You'll see the outpost right before you get to Baelgun's.", sourceObjective = "Deliver Donny's Letter to Stanwad at the Explorers' League Outpost.", progress = "News from Donny?", completion = "Yea, this isn't anything we don't already know. At least Donny's still alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11479] = { id = 11479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Crowleg\" Dan", description = "Croaker's spoken, matey. \"Crowleg\" Dan's on da ship yonder.\n\nBest go trace that blaggard, mon.  Show'im dis set's not fe be crossed.  Gaan back fe Terry when ye keelhaul 'is behind.", sourceObjective = "Confront \"Crowleg\" Dan, who is in one of the ships at Scalawag Point. Speak to Handsome Terry when you've completed this task.", progress = "I can't believe it was Dan.  Did you take care of it yet?", completion = "That's some sad news.  Dan was me old friend... AND he owed me money.  Either way, if he was working with the Southsea mongrels he got what he deserved.\n\nAs for you, my friend.  You're on your way up.  Literally.", sourceObjectiveStatus = "unverified-source-field" }
quests[11480] = { id = 11480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Number Two", description = "All the good work you've done for us hasn't gone unnoticed, {name}.  Our second in command, the delightful Annie Bonn, is incredibly impressed with what you've done so far and wants to meet you.", sourceObjective = "Speak to Annie Bonn at Scalawag Point.", completion = "Well, well, well.  If it isn't {name}.  You show up at Scalawag point, no one's heard of you except some goblin friend of that half-wit Terry.\n\nLet's just say I'm a bit... skeptical... of your intentions here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11481] = { id = 11481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crisis at the Sunwell", description = "By the naaru, I thank you, {race}, for your efforts.\n\nOur work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued.\n\nOur forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau.\n\nYou are needed there, {name}. Report to Larethor. Tell him that I wish we could spare more men.", sourceObjective = "Adyen the Lightwarden on the Aldor Rise in Shattrath City has requested that you travel to Sunwell Plateau and speak with Larethor.", completion = "Another soldier from Shattrath? A welcome sight!\n\nWish there were more of you, but we'll make due with what we have. Whatever's going on out here won't wait for us to make ready.\n\nHave a look around, {class}. There's much that needs doing. Pitch in and do your share.\n\nOh, yeah, and don't go tauntin' the cryers - err, Scryers. Looks like we're in this thing together....", sourceObjectiveStatus = "unverified-source-field" }
quests[11482] = { id = 11482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duty Calls", description = "Hear me, {race}.\n\nDuty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately.\n\nI'm afraid I have no more information to share, except this:\n\nYou'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive.\n\nApparently, the situation calls for us to set our differences aside and join forces.\n\nPrepare yourself, friend. This sounds serious.", sourceObjective = "Dathris Sunstriker on Scryer's Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell.", completion = "Welcome to Sunwell Plateau, cryer - What's that? Oh Scryer, yes of course. Isn't that what I said?\n\nWell, now, let's get a few things straight. There's some serious business going on behind those walls and it's in the interest of both of our people to address it. And since neither of us have the forces to go it alone, we're going to work - TOGETHER. Got that?\n\nNow let's get started, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[11483] = { id = 11483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Can Rebuild It", description = "Tools? Check. Materials? Negative.\n\nIf we're going to build this thing, you're going to have to get me the materials.\n\nFirst things first, {name}. For the skeletal structure I'm going to need a large barrel from Nifflevar, some dark iron ingots from Valgarde, and industrial strength rope from Baleheim.\n\nNifflevar and Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also to the northwest. Speak with McGoyver to get the ingots. He'll fly you back here once you're all done.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Large Barrel, Industrial Strength Rope and Dark Iron Ingots.", progress = "Have you got the infrastructure materials?", completion = "Excellent. These combined with the skin will make for a flawless clone of the constructs the iron dwarves use.", sourceObjectiveStatus = "unverified-source-field" }
quests[11484] = { id = 11484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have the Technology", description = "While the infrastructure for a piece of machinery like this is important, we can't underestimate the appearance of the construct. If we're to fool the iron dwarves the clone must be exact!\n\nI can make this happen.\n\nBring me a pristine shoveltusk hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or Baleheim to the northwest.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Pristine Shoveltusk Hide and Steel Ribbing.", progress = "We'll be back collecting our relics in no time!", completion = "I'll have the construct all ready to go as soon as the infrastructure is complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[11485] = { id = 11485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Rune Constructs and You: Rocket Jumping", description = "Alright, {name}; the time has come for you to climb inside this thing and learn how to use its basic abilities. When you're ready, get on the work bench and I'll get you situated inside the construct.\n\nYour first lesson is going to be using the construct's transportation system. You'll notice that the iron dwarves have set up special rune carvings around the dig site. Their constructs use those rune carvings to power up and fly from point to point. Try it with the rune carving I built here.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Rocket Jump ability at Walt's Iron Rune Carving.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Don't take any lip from these naysayers!", completion = "You're almost ready to take this work of art into the field, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11488] = { id = 11488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "Welcome to the Sunwell, {class}. Get yourself settled in and contribute however you can - there's much to do!\n\nMe? Yes, I have a little something that needs doing, but I'm not sure you're up to the task.\n\nWe've had a contact embedded in Magisters' Terrace gathering intelligence for us. He's recently failed to report and I'm growing concerned.\n\nThe terrace is just up the rise to the east. The information he was collecting is vital to our mission.\n\nThink you can handle it, {race}?", sourceObjective = "Exarch Larethor at the Shattered Sun Staging Area wants you to search Magisters' Terrace and find Tyrith, a blood elf spy.", completion = "...Come closer, {race}... Listen carefully to my words....", sourceObjectiveStatus = "unverified-source-field" }
quests[11489] = { id = 11489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Rune Constructs and You: Collecting Data", description = "The most important part of your job while controlling the construct is the collection of data. I've placed an iron dwarf relic in the cart over yonder. It's the floating, lightning infused crystal.\n\nGet on the work bench and I'll put you back in the construct. Once you're back in the driver's seat, use the construct's data collection ability to pick up the test data.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability while standing near the Iron Dwarf Relic.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Fits like a glove, don't it?", completion = "Perfect! Works like a charm!", sourceObjectiveStatus = "unverified-source-field" }
quests[11490] = { id = 11490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scryer's Scryer", description = "Go to the terrace... use the orb.\n\n<Tyrith gasps for breath.>\n\nHurry... they must be stopped... before they can....\n\n<Tyrith dies.>", sourceObjective = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace.", progress = "Go and peer into the orb, mortal.", completion = "I consider it to be no coincidence that our paths cross this day.\n\nI sense the tendrils of destiny....", sourceObjectiveStatus = "unverified-source-field" }
quests[11491] = { id = 11491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Rune Constructs and You: The Bluff", description = "You always gotta have a contingency plan in case your main plan backfires! That's why I've built in some anti-intelligence systems into the construct.\n\nYour shiny new ride might rouse some suspicion while you're at Baelgun's excavation site. That's what your bluff ability is for! Just use that any time you're confronted and you'll be safe from harm.\n\nTest it out on Lebronski by walking on his rug. Once he starts huffin' and puffin', use the bluff!\n\nGet on the work bench when you're ready to begin.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Bluff ability on Lebronski after you've walked on his rug.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Don't worry about him, {name}. He'll get over it...", completion = "You showed him! Now it's time to put you in the field.\n\nFeeling confident, I hope...", sourceObjectiveStatus = "unverified-source-field" }
quests[11492] = { id = 11492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Kill", description = "Welcome to the Sunwell, mortals. Your arrival is indeed timely.\n\nAs you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. Find him, mortals. He must again be stopped.\n\nOther, equally urgent matters require my immediate attention. I shall leave Kael's fate to you. Do not fail.\n\nWith luck, we shall speak again.", sourceObjective = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor at the Shattered Sun Staging Area.", progress = "Well, {class}, I must admit, I wasn't sure I'd see you again.\n\nWhat news do you bring?", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.\n\nI've underestimated you, {race}. Please, accept this on behalf of the Sunwell Offensive - a gift worthy of a hero such as yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[11494] = { id = 11494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Infused Relics", description = "Your construct is ready to go. All abilities have been given a once over and I've programmed the machine to both comprehend and speak the language of the titans.\n\nTake the construct to Baelgun's Excavation Site, due south of here, and collect data from the lightning infused relics that litter the site. Remember to bluff any iron dwarves that suspect your construct to be a fake. And don't forget about rocket jumping from rune to rune to get around in there!\n\nGet on the table when you're ready!", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability to collect 15 sets of Iron Rune Data.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", completion = "And once again Walt proves that he is indeed the top dwarf! What do you think of my construct now, Lebronski!\n\nThank you, {name}. This data will undoubtedly prove to be invaluable - as soon as I figure out how to get it out of the construct.", sourceObjectiveStatus = "unverified-source-field" }
quests[11495] = { id = 11495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Delicate Sound of Thunder", description = "The cavern that we opened at Baelgun's was the one place that most steered clear of... Can't say I blame 'em. The sound of thunder shot out of that cave, {name}! Loud, booming thunder!\n\nI think near the end, it was abandoned by all. Bad, bad things happened to any that went in to explore - most never coming back.\n\nI want you to check that cave out while you're at Baelgun's. Explore around the titan statue inside and report back with your findings.", sourceObjective = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct to explore the thundering cave at Baelgun's Excavation Site.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Any luck?", completion = "Incredible! What could those iron menaces be up to? What are they doing in the Storm Peaks? And what is this Loken!? I'll forward this information to our central base of operations in the Dragonblight, {name}. I'll also let 'em know that you were invaluable in the acquisition of said info.", sourceObjectiveStatus = "unverified-source-field" }
quests[11496] = { id = 11496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sanctum Wards", description = "Our first priority is to capture the Sun's Reach Sanctum.  Once we've secured it, we'll be able to use its energy to open a portal from Shattrath.\n\nThe sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves.  Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards.\n\nHunt down the Wretched and get the mana remnants they carry.  Use them to energize the sanctum wards.", sourceObjective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the Sun's Reach Sanctum to the east.", completion = "Good work, {name}.  The wards are slowly regaining their power.  The sanctum will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11497] = { id = 11497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.", sourceObjective = "Speak with Ilsa Blusterbrew at Wildhammer Stronghold in Shadowmoon Valley.", completion = "So, me boyo, Nutral, sent ya along did he?  Good man... I'll need ta remember ta send him along a pint fer all o' the business he's sendin' me way.\n\nIf it's the learnin' o' how ta fly right and proper yer after, ye've come ta the right place. No one flies finer than us Wildhammer and those we train. Fer a fee, and not a small one mind ya, I'll teach ya how ta soar through the skies!\n\nAnd when yer done, don't forget ta talk ta Brunn over there about buying one o' these gryphon beauties!", sourceObjectiveStatus = "unverified-source-field" }
quests[11498] = { id = 11498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.", sourceObjective = "Speak with Olrokk at Shadowmoon Village in Shadowmoon Valley.", completion = "Blood and thunder, Nutral sent me another ground grunt! Good man... for a draenei.\n\n<Olrokk spits on the ground near your feet.>\n\nYou've come to the right place if you want to learn how to ride your own mount through the skies. In return for a big sack of gold, I'll teach you what you need to know and not fall dishonorably to your death.\n\nAnd when you're done, don't forget to talk to Dama Wildmane over there about buying one of the windriders from our stable!", sourceObjectiveStatus = "unverified-source-field" }
quests[11499] = { id = 11499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Signet Ring of Prince Kael'thas", description = "{class}, today I ask the impossible. Today, you must obtain the signet ring of Kael'thas Sunstrider, lord of the blood elves!\n\nIt's true, the rumors of his death within Tempest Keep were ill-founded. He has appeared once more, this time at the Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for someone else to tell you. What I know is that I have innumerable collectors interested in his princely ring, and I mean to acquire it for them.\n\nOr rather, I mean for you to do so.", sourceObjective = "Wind Trader Zhareem has asked you to obtain The Signet Ring of Prince Kael'thas. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed at the Magisters' Terrace on Heroic difficulty.", progress = "The Magisters' Terrace must be a very dangerous place indeed being so close to the Sunwell.\n\nI trust that you're not having second thoughts?", completion = "So, the blood elf prince is truly dead this time? A pity, I always thought he had class. To think that one so lofty could be brought down for such a paltry sum.\n\nBut as they say, business is business. Your reward is earned, adventurer.\n\nCome back tomorrow and I will have another request for you to fulfill.", sourceObjectiveStatus = "unverified-source-field" }
quests[11500] = { id = 11500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Sisters of Torment", description = "It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang.\n\nMah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas.\n\nYou will do this thing to earn the bounty, or you will not.", sourceObjective = "Nether-Stalker Mah'duun wants you to slay 4 Sisters of Torment. Return to him in Shattrath's Lower City once you have done so in order to collect the bounty.", completion = "Who can say why the demonic sisters needed to be slain? Do you care?\n\nMah'duun thinks you care enough to collect the bounty, though.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11501] = { id = 11501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News From the East", description = "Westguard needs to know what's going on here, {name}. I want you to personally deliver the news to Captain Adams.\n\nWhenever you're ready, let me know and I'll put you back in the construct for one final flight. It'll take you to Westguard Keep, but more than likely blow up in the process.\n\nIt's been a pleasure...", sourceObjective = "Speak with Captain Adams at Westguard Keep.", completion = "Wonderful... As if having the Scourge all up our you-know-whats wasn't enough, now we got some angry ancient titan construct to deal with!\n\nI'll need some time to chew on this information, {race}. In the meantime there's plenty of work that needs doing here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11502] = { id = 11502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Defense of Halaa", description = "We are not a warlike race, {race}.  However when war comes to our lands, we do not run away from it.\n\nThe Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous.  The history between our people and the orcs is one of bloodshed and betrayal.\n\nGo and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.", sourceObjective = "Defeat 10 enemy players in Halaa and return to Lakoor in Telaar.", completion = "I thank you, {name}.  Your efforts will not be ignored.", sourceObjectiveStatus = "unverified-source-field" }
quests[11503] = { id = 11503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies, Old and New", description = "Our ancient enemy, the draenei, have returned with powerful allies.  They wage war in Halaa, southwest of here.\n\nWe cannot allow them a victory there as Garadar would be next without a doubt.\n\nGo and slay those who would aid our ancient enemy.", sourceObjective = "Defeat 10 enemy players in Halaa and return to Karrtog in Garadar.", completion = "You bring great honor to our people.  You have our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11504] = { id = 11504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Rise!", description = "The path east of us is a primary hunting trail of the tuskarr. At least that's what it used to be...\n\nMore recently our hunters have been returning to Kamagua claiming that the dead have risen and are out for blood! That is what has brought my son and me here. Elder Atuik asks that we find resolution in the bluffs.\n\nWill you assist us in our time of need? I seek heroes willing to brave the perils of Shield Hill, southeast of here. Search the desecrated graves for clues and return your findings to me.", sourceObjective = "Orfus of Kamagua at the Ancient Lift in the Howling Fjord wants you to find Fengir's Clue, Rodin's Clue, Isuldof's Clue and Windan's Clue.", progress = "The tuskarr need your help!", completion = "<Orfus's whiskers bristle.>\n\nPirates... Is there no end to the depths of their depravity?\n\nWe must recover the stolen artifacts and return them to this cursed place so that my people may once more know peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[11505] = { id = 11505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Auchindoun", description = "Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region.\n\nAncient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day.  If you can help secure a tower during these times, you will have helped bring the spirits to our side.\n\nShould we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.", sourceObjective = "Help the Alliance secure a tower in the Bone Wastes.", progress = "The spirits are restless, {name}.  Have you accomplished your task?", completion = "The spirits are one step closer to resting in peace.  It is good to incur their favor, especially when waging war so close to their place of rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[11506] = { id = 11506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of Auchindoun", description = "The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance.\n\nThe draenei's custom required them to pay their respects at spirit towers at various times during the day.  If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun.\n\nThe Alliance will try to capture the towers in order to secure the dead's favor.   We must ensure that our side succeeds instead.", sourceObjective = "Help the Horde secure a Spirit Tower in the Bone Wastes.", progress = "The spirits of Auchindoun are all around us.  Will they grant us their boon?", completion = "The spirits are closer to finding peace and have bestowed their favor onto us.\n\nA humiliating blow to our enemy that their own ancestors would side against them, even if only temporarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[11507] = { id = 11507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Atuik and Kamagua", description = "<Orfus bundles up the clues you brought him.>\n\nMy people are bitterly entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must take these clues to him at once.\n\nTo get to Kamagua you must take the Ancient Lift, behind me. Take the lift directly to Kamagua and find Elder Atuik.", sourceObjective = "Orfus of Kamagua in the Howling Fjord wants you to deliver Orfus's Bundle to Elder Atuik at Kamagua.", progress = "News from Orfus?", completion = "Orfus is a good tuskarr - one of our strongest warriors. I knew he would not let us down.\n\nAllow me to see what it is that you have brought.", sourceObjectiveStatus = "unverified-source-field" }
quests[11508] = { id = 11508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezzix Spindlesnap", description = "The pirate thieves have set up port at Scalawag Point, far to the south. Unfortunately, they have fortified their camp with many deadly defenses.\n\nThere is someone that might be able to assist us in infiltrating Scalawag.\n\nA pirate mercenary by the name of Grezzix Spindlesnap recently came to our village in search of food and shelter. In exchange he gives us information about our enemies and feeds them misinformation about our attack plans. Seek him out at his ship just off the coast here - southwest.", sourceObjective = "Speak with Grezzix Spindlesnap.", completion = "Yarr, matey. Grezzix never did like to get his hands dirty! A pirate's life for Grezzix is a good one, so long as Grezzix doesn't have to do any of the work.\n\nI've seen those artifacts. It's the reason I'm here and not at Scalawag myself! Bad, bad things those are...\n\nHey, it's your life though, right? You wanna get inside Scalawag and Grezzix can help.", sourceObjectiveStatus = "unverified-source-field" }
quests[11509] = { id = 11509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Street \"Cred\"", description = "The Northsea Freebooters all fear and respect Grezzix. I'm thinking they recognize my special talents and envy my amazing ship. All you need to do is tag along with my cabin boy, Lou, and you'll be in like... In like tin. Pirates love tin.\n\nJust talk to Lou when you're ready to go and he'll take you to Scalawag.\n\nOh yea, you'll want to talk to \"Silvermoon\" Harry first. He'll have more information on the stuff they pilfered. Just watch what you say around him. He's a freak... crazy for blood elves.", sourceObjective = "Speak with \"Silvermoon\" Harry at Scalawag Point about the missing Vrykul artifacts.", completion = "<Harry raises an eyebrow at you.>\n\nSo you're like me, eh? A little eccentric.\n\n<Harry whispers.>\n\nNobody dresses like that around here.\n\nAbout those artifacts... Everyone that came into contact with that stuff has ended up dead, missing or both.\n\nIf you're still interested in learning more, I can help - but it'll cost you.\n\n<Harry winks.>\n\nYou scratch my back and I'll try to not stick a dagger in yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[11510] = { id = 11510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Scoodles\"", description = "One of the first things Jonah Sterling did after he went crazy was to take my prized sin'dorei scrying crystal and feed it to the bane of my existence, \"Scoodles\" the orca.\n\nNo I didn't name the damned thing. I just know that she swims out past the ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my beautiful sin'dorei crystal from its stomach.\n\nDo this and we can get down to business.", sourceObjective = "\"Silvermoon\" Harry at Scalawag Point wants you to recover his Sin'dorei Scrying Crystal from the orca, \"Scoodles.\"", progress = "Are you lost?", completion = "<Harry takes the crystal from you and gently pets it.>\n\nOh my precious! Did the big, mean whale hurt you? It'll be ok. I'll never let you out of my sight again!\n\n<Harry looks up at you.>\n\nSo, where were we?", sourceObjectiveStatus = "unverified-source-field" }
quests[11511] = { id = 11511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Staff of Storm's Fury", description = "Those artifacts are cursed and you'd be crazy to go looking for them, {race}. I know for certain that anyone that's come into direct contact with any of those items has either gone mad or been killed.\n\nTake that staff, for example. Last I heard the ship that held it was abandoned and left to rot on the coast of the Isle of Spears, north of here.\n\nIf you want that thing, check the ship's hold.\n\nWhatever you do, don't bring that staff back here! And steer clear of Abdul! He'll tear your heart out.", sourceObjective = "Recover the Staff of Storm's Fury and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "You have the staff?", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11512] = { id = 11512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Heart of Isuldof", description = "Some say Jonah was never quite right in the head, but I know the truth. It was the heart. That damned frozen heart! I saw the change in him the second he pulled it from the grave. I could see the blood freeze in his veins... It was then that the madness truly took over.\n\nHe left us to hole up in his cave on the north side of this island. Last I heard he had thrown the heart in the back of his bear den. Too little, too late...\n\nI'll kill you myself if you even think about bringing that heart back here!", sourceObjective = "Recover the Frozen Heart of Isuldof and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "The... The Frozen Heart of Isuldof?", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11513] = { id = 11513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepting the Mana Cells", description = "I have devised a plan to acquire a power source strong enough for the creation of our portal.\n\nThe ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas.\n\nThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.\n\nJust beware the mana cells' phase wyrm guardians.", sourceObjective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", progress = "Did you acquire the mana cells?", completion = "These mana cells are vital to our efforts. We will have the portal to the Sunwell Isle created in no time!\n\nReturn tomorrow and I will send you out to acquire more of them from our Bash'ir 'friends'.", sourceObjectiveStatus = "unverified-source-field" }
quests[11514] = { id = 11514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maintaining the Sunwell Portal", description = "We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the north.\n\nRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.\n\nJust be cautious of the phase wyrms that they use to guard the mana cells.", sourceObjective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", progress = "{name}, how fare your efforts to obtain mana cells for us this day?", completion = "These mana cells will continue to power the portal.\n\nReturn tomorrow and I will send you out to obtain more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11515] = { id = 11515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood for Blood", description = "When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift.  They  stayed behind and gorged themselves on the blood of demons for days.\n\nThe blood has changed them, given them new powers.  It will also prove their undoing.\n\nObtain blood samples from other demons.  Use them to power this fel siphon and deprive these arrogant fools of their new powers.  Slay them in their weakened state and return to me.", sourceObjective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to kill 4 Emaciated Felbloods by using the Fel Siphon on them. You will need Demonic Blood from nearby Wrath Heralds to power the Fel Siphon.", progress = "These freaks are a disgrace to our race.  You must destroy them, {name}.", completion = "Fools.  They learned to drain fel energy but did not learn how to retain it.\n\nWe were lucky, {name}.  An experienced felblood would've surely been a formidable opponent.", sourceObjectiveStatus = "unverified-source-field" }
quests[11516] = { id = 11516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast the Gateway", description = "We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas.\n\nTake these embers, they contain one of my creations: a living flare.  It is designed to act as a powerful destructive force - as long as it has been provided enough energy.\n\nFind the fel sparks that wander the area and slay them near the living flare.  The flare will grow in power each time, until it becomes unstable.\n\nOnce you've achieved this bring the flare to the gateway.  It will know what to do.", sourceObjective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to use the Sizzling Embers to summon a Living Flare and slay Incandescent Fel Sparks near it until it becomes an Unstable Living Flare. Return to the Legion Gateway with the Unstable Living Flare to destroy it.", progress = "Is it done, {name}?  We must stop further Legion forces from reinforcing Kael'thas.", completion = "Excellent work, {name}.  The demons might repair the gateway in due time.  I suppose we'll just have to blow it up again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11517] = { id = 11517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nasuun", description = "I am most glad that you are here, {class}! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", sourceObjective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", completion = "Portanuus sent you? Good, we haven't any time to spare!", sourceObjectiveStatus = "unverified-source-field" }
quests[11519] = { id = 11519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Shield of the Aesirites", description = "If you listen real close you can hear cannon fire coming from the northeast. That's Captain Ellis's ship, Sister Mercy. Thing is, Ellis and his entire crew were killed 'bout a month ago.\n\n<Harry nods.>\n\nGhost ship...\n\nIf it's info you be wantin' 'bout the shield, Ellis is the man to ask.\n\nSister Mercy docks on the small island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout once every five minutes. There be no shortage of souls 'round these parts...", sourceObjective = "Speak with Captain Ellis aboard the Sister Mercy.", completion = "Arrr, me'n'me crew pilfered that thar shield! We be tryin' to get her back from that no good, landlubbin' scallywag, Sorlof! Ye come to help, arrr?\n\nWell, as ye can see we be runnin' a skeleton crew!\n\n<Captain Ellis laughs.>\n\nSister Mercy be needin' another powder monkey to man the big'uns o'er on the poop deck. Think ye be up to the job, me hearty?\n\nHelp me crew take Sorlof down and we'll split the booty! Ye can have the shield, me'n'me crew gets the rest!", sourceObjectiveStatus = "unverified-source-field" }
quests[11520] = { id = 11520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discovering Your Roots", description = "Greetings, {race}.\n\nI'm afraid I have little to offer here until my reagents are stocked.\n\nOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.\n\nFortunately, I know a secret....\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.", sourceObjective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", progress = "Really, {name}, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "These should do nicely, {class}.\n\nI thank you for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11521] = { id = 11521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rediscovering Your Roots", description = "My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand.\n\nCollecting the roots is difficult, but I know a special method of extraction.\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.\n\nReturn to me, {name}, once you have collected five of the roots.", sourceObjective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", progress = "Really, {name}, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "Excellent work, {name}.\n\nThank you again for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[11523] = { id = 11523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arm the Wards!", description = "We've succeeded in reactivating the crystal wards around the sanctum, but why stop there?  We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards.\n\nHunt them down and get the mana remnants they carry.  Use the remnants to energize the sanctum wards; the safety of our operation depends on it.", sourceObjective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the structures in Sun's Reach.", progress = "Have you reactivated a crystal ward, {name}?", completion = "Good work, {name}.  The wards are slowly regaining their power.  Sun's Reach will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11524] = { id = 11524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erratic Behavior", description = "We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor.\n\nThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.\n\nI've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.", sourceObjective = "Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", progress = "Have you converted the sentries, {name}?", completion = "Good job, {name}.  The sanctum will be ours in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11525] = { id = 11525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Conversions", description = "My plan to replace the damaged crystals on the erratic sentries has been a success.  We've managed to take the Sun's Reach Sanctum with their help.\n\nI've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries.  We'll deploy them to other locations once they're converted.", sourceObjective = "Vindicator Xayann at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", progress = "Have you converted the sentries, {name}?", completion = "Excellent.  The converted sentries will help to secure our perimeter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11526] = { id = 11526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Magistrix", description = "We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here.  She never returned.\n\nTake this scroll we found on one of the enemy corpses.  We believe it will grant you access through the portal.  Once through, find Magistrix Seyla and aid her in any way you can.", sourceObjective = "Use the Captured Legion Scroll near the portal at Dawning Square. Once you've gone through the portal, find Magistrix Seyla.", progress = "Keep quiet, {class}.  The Legion's forces watch the south of the gate.", completion = "It's very sweet of Theris to worry about my hide, but we've got bigger problems here.  Much bigger.", sourceObjectiveStatus = "unverified-source-field" }
quests[11527] = { id = 11527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutiny on the Mercy", description = "Aye, we got problems, matey. Me gunners have mutinied! M'n'the crew up top be tryin' to kick Sorlof's keester while dealin' with the mutinous gunners down'blo.\n\nYe're gonna have to go down'blo and deal with those mutinous sea dogs and take their blastin' powder for the big'un o'er on the poop deck.\n\nWith ye mannin' the big'un, Sorlof is sure to die and give up the booty!", sourceObjective = "Captain Ellis aboard the Sister Mercy in the Howling Fjord has asked that you recover 5 Barrels of Blasting Powder from the ship's hold.", progress = "Mutinous sea dogs and giants abound!", completion = "Here's to hopin' those treacherous bilge rats learned their lessons! Now it be time to man the big'un, matey!", sourceObjectiveStatus = "unverified-source-field" }
quests[11528] = { id = 11528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", sourceObjective = "A small tag on this present reads:\n\nHappy holidays, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11529] = { id = 11529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorlof's Booty", description = "Me crew is gonna get the big'un all primed an'ready for ya, matey. She's restin' snuggly on the bow, o'er on the other side of the ship. Go'n man it and be ready to fire when Sorlof is in our sights!\n\nOnce we take that landlubber down, ye'll have to recover the booty for us, seein' as how we can't leave the damned ship! Bring that booty back to me and ye'll get your cut - the shield...", sourceObjective = "Slay Sorlof using the Big Gun and recover Sorlof's Booty. Return Sorlof's Booty to Captain Ellis aboard the Sister Mercy.", progress = "Smartly, me hearty!", completion = "A deal's a deal, me hearty!", sourceObjectiveStatus = "unverified-source-field" }
quests[11530] = { id = 11530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shield of the Aesirites", description = "Here's yer shield. Me hopes it doesn't curse ye like it did me'n'me crew. Ye don't have to go home, but ye can't stay here... I be certain that thar be some that would be interested in getting' it back.\n\nNow get that thing off me ship!", sourceObjective = "Return the Shield of the Aesirites to Orfus of Kamagua at the Ancient Lift in the Howling Fjord.", progress = "You have returned!", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11531] = { id = 11531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Engine Part", description = "This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen.  Perhaps K. Lee Smallfry might know something about it.", sourceObjective = "Take the Strange Engine Part to K. Lee Smallfry in Telredor.", progress = "Oh goodness!  What've you got there, {name}?", completion = "<K. Lee looks at the engine part and then stares off into the distance for a moment.>\n\nThis is somethin' real special.  Difficulty to say where it's from--like it just fell out of the sky.  I'm gonna hold on to this and pay you for your troubles.\n\nBetween you and me though, I think it's best if we didn't mention this to anyone.\n\n<K. Lee puts on her most charming smile.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11532] = { id = 11532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distraction at the Dead Scar", description = "The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won't last long, however.\n\nI want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges.\n\nIf all goes well, they won't even notice us taking the armory from Kael's lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.", sourceObjective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", progress = "Have you accomplished your mission, {name}?", completion = "You've got some real talent, kid.  Did you ever think of joining the Skyguard?\n\nI jest, {name}.  We need you here if we want to take the docks any time soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11533] = { id = 11533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Air Strikes Must Continue", description = "We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar.\n\nAs a matter of fact, it's gone so well that we're going to continue our air strikes against them.  Take these arcane charges and use them against their forces.\n\nTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.", sourceObjective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", progress = "Have you accomplished your mission, {name}?", completion = "Any demons we kill today are demons that we do not have to fight tomorrow.  Keep it up.", sourceObjectiveStatus = "unverified-source-field" }
quests[11534] = { id = 11534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nasuun", description = "I am most glad that you are here, {class}! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", sourceObjective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", completion = "Portanuus sent you? Good, we haven't any time to spare!", sourceObjectiveStatus = "unverified-source-field" }
quests[11535] = { id = 11535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Ready", description = "Supplies are inbound, or so I'm told.\n\nRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.\n\nAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.\n\nThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.\n\nRelieving them of their ore will help our efforts in more ways than one....", sourceObjective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I need?", completion = "Excellent! We're getting closer....\n\nSoon I'll be able to craft an anvil, then the real work can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[11536] = { id = 11536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stop Now....", description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.\n\nThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", sourceObjective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I asked for?", completion = "Excellent! This will help me keep our soldiers in weapons and armor.\n\nYour help is truly making a difference!", sourceObjectiveStatus = "unverified-source-field" }
quests[11537] = { id = 11537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Must Go On", description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you succeeded, {name}?", completion = "Your dedication is exemplary, {name}.  We will show the forces of the Burning Legion what we're capable of.", sourceObjectiveStatus = "unverified-source-field" }
quests[11538] = { id = 11538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for the Sun's Reach Armory", description = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", sourceObjective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you done what I asked of you, {name}?", completion = "Your dedication is exemplary, {name}.  We will take the armory from the forces of the Legion in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[11539] = { id = 11539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Harbor", description = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.\n\nThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", sourceObjective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", completion = "Excellent work, {class}.  Kael's armies will falter and once we take the harbor we shall deliver the killing blow!", sourceObjectiveStatus = "unverified-source-field" }
quests[11540] = { id = 11540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Dawnblade", description = "We've driven the Dawnblade army out of the Sun's Reach Harbor.  Sun's Reach is ours in its entirety.  Yet somehow... I'm not entirely satisfied.\n\nI want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants.  They sealed their fate when they followed Kael to this place.", sourceObjective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", progress = "Have you slain the Dawnblade scum, {name}?", completion = "What thoughts go through Prince Kael'thas Sunstrider's head when he hears of his armies' defeats?\n\nDoes he feel despair?  Helplessness?  Fear?\n\nI sure hope so.", sourceObjectiveStatus = "unverified-source-field" }
quests[11541] = { id = 11541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt the Greengill Coast", description = "The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs.\n\nIt's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in.\n\n{class}, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free.\n\nMy guess is that the murlocs will be incensed and turn on their masters.", sourceObjective = "Captain Valindria wants you to free 10 Greengill Slaves. Return to her onboard the Silvermoon's Pride at Sun's Reach Harbor once you have done so.", progress = "My scouts tell me that there hasn't yet been enough disruption of the naga today.", completion = "That's enough for today. Slow and steady is the key here. Too much disruption and they'd turn their attention directly upon us; something that we don't want.\n\nCome back again tomorrow and we'll work on it some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[11542] = { id = 11542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercept the Reinforcements", description = "We're making a push to solidify our control of Sun's Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", sourceObjective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", progress = "Have you accomplished your task, {name}?", completion = "Well done, {name}.  It should be a long time before the harbor receives any reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[11543] = { id = 11543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Enemy at Bay", description = "We've managed to capture Sun's Reach in its entirety.  Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.  You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", sourceObjective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", progress = "Have you accomplished your task, {name}?", completion = "Well done, {name}.  It should be a long time before the harbor receives any reinforcements.", sourceObjectiveStatus = "unverified-source-field" }
quests[11544] = { id = 11544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ata'mal Armaments", description = "The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor.\n\nI need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them.\n\nRetrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.", sourceObjective = "Smith Hauthaa needs you to produce 5 Cleansed Ata'mal Metal. Do so by breaking down Ata'mal Armaments on her anvil at the Sun's Reach Armory on the Isle of Quel'Danas.", progress = "I need all of the cleansed Ata'mal metal that I can get my hands on, {class}.", completion = "Thank you, my friend. Now I will be able to fashion more of the special alloy that is going into the creation of our forces' weapons and armor.\n\nAnd, I have some leftover extract from the process, which you'll likely find handy for use on your weapons. Please, take your pick of whichever will serve your purposes.\n\nReturn to me again on the morrow. No doubt I will need more armaments.", sourceObjectiveStatus = "unverified-source-field" }
quests[11545] = { id = 11545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Charitable Donation", description = "We've taken Sun's Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.\n\nIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.", sourceObjective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, {name}.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11546] = { id = 11546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Open for Business", description = "Welcome, {name}.\n\nThere are a number of ways I can assist you in your efforts here.\n\nFor example, I've recently discovered a recipe for a unique elixir.\n\nThe bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites.\n\nBring me a sample from the nearby bushes and I'll show you what I mean.", sourceObjective = "Mar'nah at the Sun's Reach Harbor wants you to gather 5 Bloodberries from the bushes found on Quel'Danas.", progress = "Have you gathered those berries yet?", completion = "Excellent, {name}.\n\nI hope this will aid you in your efforts here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11547] = { id = 11547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Your Ley Lines", description = "Freeloaders!\n\nYou all want instant gratification - never giving thought to the effort required to create even the simplest of portals.\n\nPerhaps a little education will instill a bit of gratitude for my ceaseless efforts.\n\nTake this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast.\n\nPerhaps then you'll appreciate your precious translocations....", sourceObjective = "Astromancer Darnarian in the Sun's Reach Sanctum wants you to use the Astromancer's Crystal at the Bloodcrystal, the Dawning Square portal, and the naga shrine at Greengill Coast.", progress = "Have you attuned the crystal yet, {class}?", completion = "Yes, yes. Let's have a look now, shall we?\n\nThings seem to be in order. Very well. Here is your translocator.\n\nIf any of your readings are faulty, there's no telling where you'll end up, and mind you, you'll only have yourself to blame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11548] = { id = 11548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Continued Support", description = "We've built a memorial to honor those slain in battle.  It's but a small consolation to the families that lost their loved ones.\n\nI am taking up a collection to aid the orphans and spouses of our war heroes.  If you can spare a small donation it would go a long way.", sourceObjective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, {name}.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11549] = { id = 11549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Magnanimous Benefactor", description = "You've done so much for us, {name}.  We greatly appreciate your assistance.\n\nYou might have noticed Anchorite Ayuri's efforts outside.  She has a big heart and is very convincing, but the donations do not quite add up to what she had expected.\n\nIf you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide.  What do you say?", sourceObjective = "Anchorite Kairthos wants you to donate 1000 gold to aid in Anchorite Ayuri's efforts. You will be known as {name} of the Shattered Sun if you complete this quest.", progress = "Are you ready to make the contribution?", completion = "You truly are a generous person and a worthy ally.  From now on you shall be known as {name} of the Shattered Sun and all who fought here will know of your deeds!", sourceObjectiveStatus = "unverified-source-field" }
quests[11550] = { id = 11550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter, the Deceiver...", description = "Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival.\n\nThe object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now.\n\nReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.", sourceObjective = "Report to Archmage Ne'thul on the Isle of Quel'Danas, north of Quel'Thalas.\n\nFlight masters in Ironforge and Silvermoon City will get you to your destination.", completion = "Kil'jaeden bears down upon this world with the full force of the Burning Legion. Should the summoning complete, our world will once more be flung into the throes of chaos. Your assistance on the Isle of Quel'Danas is critical to our success against the Burning Legion.\n\nOur mages are working on bringing down the barriers blocking access to the Sunwell. Do your part in battling the forces of the Legion by helping the Shattered Sun Offensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[11551] = { id = 11551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamath, the First Gate" }
quests[11554] = { id = 11554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friend in the Frontlines", sourceObjective = "Your aid in the offensive has not gone unnoticed, {name}.  The combined forces of the Aldor and Scryers offer you their thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11555] = { id = 11555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honored by Your Allies", sourceObjective = "You continue to prove yourself in this most important battle, {name}.  Please accept this as a token of our continued gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[11556] = { id = 11556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered in the Field of Battle", sourceObjective = "We couldn't have gotten where we are without you, {name}.  The combined might of the Aldor and Scryers is not enough to crush the Legion and Kael.  We are thankful to have allies of your caliber among us.", sourceObjectiveStatus = "unverified-source-field" }
quests[11557] = { id = 11557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exalted Among All Combatants", sourceObjective = "You are one of our very best, {name}.  Your name will be known throughout our ranks for a long time to come.\n\nPlease accept this small gift on the behalf of our forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[11558] = { id = 11558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", sourceObjective = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.", progress = "Was I right to worry? Have our idiot guardians been overcome?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this.", sourceObjectiveStatus = "unverified-source-field" }
quests[11559] = { id = 11559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfin Commerce", description = "Now that you can speak with the Winterfin, it is time for you to let them get to know you. One of the best ways to do that is to conduct business with them.\n\nThe murlocs prize clams over any other object and their only surviving merchant is Ahlurglgr. If I were you, I'd collect a handful of Winterfin clams and give them to him as a gift.\n\nThe clams can be found all over down in the trench, as well as across it in the Winterfin village and their caverns.", sourceObjective = "Collect 5 Winterfin Clams and deliver them to Ahlurglgr at Winterfin Retreat.", progress = "What's this? Who are you?\n\nYou're one of those {race} things! How can you speak our tongue?", completion = "These are for me? Is this some sort of {race} trick? No?\n\nWell then, thank you! Come back any time that you have more clams, and we'll do business!", sourceObjectiveStatus = "unverified-source-field" }
quests[11560] = { id = 11560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Noes, the Tadpoles!", description = "Oh good, you're back!\n\nWhen the landslide at the village across the water exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and stole the Winterfin tadpoles away.\n\nSomething happened to all of the murlocs that followed him in there, and when they re-emerged, they were under his control.\n\n{class}, you must swim across the waters and rescue the Winterfin tadpoles in the village and caverns.\n\nThe future of the Winterfin tribe depends upon you!", sourceObjective = "King Mrgl-Mrgl has asked you to rescue 20 Winterfin Tadpoles. Return to him at Winterfin Retreat once you have done so.", completion = "Now no matter what happens, the Winterfin murlocs have a secure future.\n\nYou are to be commended, and rewarded, for your selflessness, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11561] = { id = 11561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Them!", description = "Our brothers and sisters across the water are now our mortal enemies. They have kidnapped our tadpoles, driven us out of our village, and killed more of us than I can count.\n\nProve yourself, {race}! Swim across the rift and slay them!\n\nDespite the favor that the new king has shown you, only then will we consider accepting you here. Fail to do so, and you might as well leave now and never return!", sourceObjective = "Brglmurgl at Winterfin Retreat has asked you to kill 15 Winterfin murlocs. Any combination of warriors, oracles, and shorestrikers will do.", progress = "If you have killed so many of the Winterfin betrayers, why is it that when I look out across the water, I still see too many of them?", completion = "I am pleased. I can smell the coppery tang of their blood on your hands.\n\nThis is a good start for you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11562] = { id = 11562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Being Blackmailed By My Cleaner", description = "I have something embarrassing to admit: I'm being blackmailed!\n\nMrmrglmr agreed to clean some of my things, and got hold of my spare murloc costume. He's threatening to reveal my true nature to the other murlocs.\n\nI need not explain to you what a disaster that would be! Besides, I have a plan that's going to require that we get that costume back.\n\nPlease, {name}, go to Mrmrglmr at the other end of the Retreat to the north and do whatever he asks of you.", sourceObjective = "King Mrgl-Mrgl has asked you to speak with Mrmrglmr at the northwest end of Winterfin Retreat.", completion = "Aw, so you must be the so-called King Mrgl-Mrgl's lackey. I suppose that night elf has sent you to appease me?\n\nGood, I have just the thing that needs doing for someone as powerful as you!", sourceObjectiveStatus = "unverified-source-field" }
quests[11563] = { id = 11563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grmmurggll Mrllggrl Glrggl!!!", description = "If your pathetic little eyes were any good, you'd see that we're being slaughtered by the orcas to the north in the bay!\n\nAssuming your precious night elf king wants his spare costume back, I think you'll do me a favor and bring back the head of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating the hope of life for all those who hear the siren song of death upon the waves!\n\nBe quick about it, {race}, Winterfin murlocs are losing their lives even as we waste time talking!", sourceObjective = "Mrmrglmr wants you to return to him at Winterfin Retreat with Glrggl's Head.", progress = "If you don't have Glrggl's head, don't waste my time!", completion = "Not bad. This will make a nice feast!\n\nWith the king of the orcas dead the attacks upon us should diminish while the whales fight amongst themselves for dominance.", sourceObjectiveStatus = "unverified-source-field" }
quests[11564] = { id = 11564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Succulent Orca Stew", description = "Word is, strange {race}, that you might be going after the king of the orcas, Glrggl.\n\nThat's all fine and good, but if you want to taste the stew that makes life worth living, then you'll bring me back the succulent blubber of the orcas that swim in Glimmer Bay.\n\nHurry... I have quite a bit of cutting to do on this carcass if you want to reap the benefits of your efforts.", sourceObjective = "Cleaver Bmurglbrm has tasked you with acquiring 7 Succulent Orca Blubber. Return with them to him at Winterfin Retreat.", progress = "Do you have all of the orca blubber that I require?", completion = "Ah yes, these will do nicely.\n\nJust plop them down anywhere. You can have some of my leftover stew from last night.", sourceObjectiveStatus = "unverified-source-field" }
quests[11565] = { id = 11565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spare Suit", description = "Very well, your king's secret is safe with me as long as he continues to help us against our enemies.\n\nHere, take this to him. I cleaned it up nicely, though I have no idea why he needs a second disguise.\n\nMaybe he has something in mind for you?", sourceObjective = "Return King Mrgl-Mrgl's Spare Suit to him at Winterfin Retreat.", progress = "Do you have my spare suit, {name}?", completion = "<Upon seeing the spare murloc suit, the king rubs his costumed appendages together.>\n\nNicely done. Now, back to the pressing matter at hand. I've got something of great importance for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[11566] = { id = 11566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surrender... Not!", description = "The time has come to put an end to this unnatural situation, {name}. For the Winterfin murlocs to have a chance at a future, Claximus must die!\n\nI want you to take my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. With the white flag in hand, the murlocs won't attack you.\n\nYou'll find him in the southwestern most corner of the caverns. Once you get close enough, deal with Claximus. Bring me one of his claws as proof that the grisly deed has been done.", sourceObjective = "King Mrgl-Mrgl at Winterfin Retreat has asked you to bring him a Claw of Claximus.", progress = "Have you done it, {class}? Is Claximus dead?", completion = "Regrettable, but necessary. I'll take the claw, {name}.\n\nThank you for all of the help you've given us. With Claximus defeated, maybe we'll be able to reunite the remaining murlocs and seal off those caverns.\n\nPlease, my friend, take this... it's the least I can do for all of the help you have rendered us!", sourceObjectiveStatus = "unverified-source-field" }
quests[11567] = { id = 11567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Armor of the Kvaldir", description = "I was on the vessel that was bringing in the armor. We'd just boarded the ship and were headin' back here when we were attacked by a Forsaken destroyer.\n\nThey boarded our ship, took all the booty for themselves, and then sunk her.\n\nThat was the last I'd seen of that armor. If you want, you can take my bomber from Scalawag to the dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She'll get you on the bomber.\n\nIf you manage to find the stuff, don't you dare bring it back!", sourceObjective = "Recover the Ancient Armor of the Kvaldir and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "Have you found the armor?", completion = "We must return all of the artifacts, {name}. When all four are gathered, you will put them back in their graves.", sourceObjectiveStatus = "unverified-source-field" }
quests[11568] = { id = 11568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Return to Resting", description = "<Orfus hands you a satchel.>\n\nWithin this satchel are the artifacts that you recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the items were originally stolen from and return the artifacts. It is my hope that this gesture will quell the spirits that now haunt our hunting grounds.\n\nBe strong, {name}...", sourceObjective = "Use the Bundle of Vrykul Artifacts at the ransacked burial mounds of Shield Hill to return the Frozen Heart of Isuldof, the Shield of the Aesirites, the Staff of Storm's Fury and the Ancient Armor of the Kvaldir.\n\nReturn to Orfus of Kamagua at the Ancient Lift should you succeed.", progress = "Is it done? Are the spirits at rest?", completion = "Grim tidings, {name}. My people are in danger and must be warned. These sea faring aberrations will take no mercy upon the Kalu'ak.", sourceObjectiveStatus = "unverified-source-field" }
quests[11569] = { id = 11569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keymaster Urmgrgl", description = "I have to get out of these caverns! There's magic stuff seeping in from Coldarra, above, and affecting everyone's minds.\n\nI don't intend to be controlled like these others!\n\nKeymaster Urmgrgl is in the cave below and to the south. He holds the key to my cage. Get it from him and bring it back so that I can unlock my cage and get out of here.\n\nHurry!", sourceObjective = "Glrglrglr inside the Winterfin Caverns has asked you to retrieve Urmgrgl's Key.", progress = "Do you have the key?\n\nNo, I don't care about any of these others. I just want to get out of here!", completion = "Quickly, hand it here!", sourceObjectiveStatus = "unverified-source-field" }
quests[11570] = { id = 11570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from the Winterfin Caverns", description = "The lock on my cage doesn't look too solid, but I'm not foolish enough to try to leave without assistance.\n\nWill you help me safely get out of these caverns? There's no time to waste, {race}.\n\nWhen you get back to the retreat, please let the king know that I'm okay. He's sure to give you a reward.", sourceObjective = "Escort Lurgglbr to safety and then report to King Mrgl-Mrgl at Winterfin Retreat with the good news.", completion = "This is wonderful news! And you say that Lurgglbr discovered that the emanations from the caverns are what caused this insanity?\n\nIt must be that the magic from Coldarra is growing stronger. The Nexus War... the battle between the blue dragonflight and all of the other dragons, is spilling over.\n\nSoon, we will all be embroiled in it!", sourceObjectiveStatus = "unverified-source-field" }
quests[11571] = { id = 11571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning to Communicate", description = "To help, you must learn how to speak the Winterfin dialect. We'll work with the forces of nature and magic to do that.\n\nTake this empty conch shell. At the bottom of the watery trench below exists Scalder, an elemental of air and watery fury.\n\nOnce she is defeated, use the conch upon her remains to capture her magical steam. Return the full conch to me, and I'll imbue my knowledge of the Winterfin tongue into you.\n\nLuckily, a friend taught me a water breathing spell, which I will cast upon you.", sourceObjective = "King Mrgl-Mrgl has given you a conch to use upon Scalder's remains. Return The King's Filled Conch to him at Winterfin Retreat.", progress = "Have you managed to fill the conch with Scalder's steam?", completion = "Now I will be able to use Scalder's essence to impart my understanding of the Winterfin murloc tongue to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[11572] = { id = 11572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Atuik", description = "Return to Elder Atuik at Kamagua. He and the rest of my people must be warned of this impending doom that approaches from the sea.\n\n<Orfus shivers.>\n\nUse the Ancient Lift to reach him. Please hurry!", sourceObjective = "Deliver the bad news to Elder Atuik at Kamagua.", completion = "The Kalu'ak thank you for all that you have done, {name}. We must now prepare for battle and warn our brothers and sisters across the sea of what is to come.\n\nI hope it is not too late...", sourceObjectiveStatus = "unverified-source-field" }
quests[11573] = { id = 11573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orfus of Kamagua", description = "Hail, traveler. I am Lunk-tusk of the Kalu'ak. We are known as tuskarr to your people. My partner and I were recently sent up to investigate strange happenings along one of our hunting trails. It was when we approached the graveyard known as Shield Hill that we were attacked by the undead. I was lucky to make it to this camp, but I am uncertain as to what became of Orfus.\n\nWe parted ways at the Ancient Lift, southeast of here along the cliff edge. Will you go see if he is ok?", sourceObjective = "Find Orfus of Kamagua at the Ancient Lift in Howling Fjord.", completion = "Lunk-tusk lives? At least there is some good news to be had on this day...", sourceObjectiveStatus = "unverified-source-field" }
quests[11574] = { id = 11574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Close For Comfort", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts - I was surrounded!\n\nA magical box appeared above me, opened up and pulled me inside. Just as it began to close around me, my rescuers swooped in on the backs of red drakes. It was breathtaking!\n\nI never thanked them for saving me. Please, {class}, find them, and pass on my gratitude.", sourceObjective = "Endorah wants you to go to Amber Ledge north of Warsong Hold and thank those there for rescuing her.", completion = "You can tell your friend that her rescue was our pleasure, as well as our duty.\n\nHer encounter was but a small piece in what I believe to be a large puzzle.\n\nDalaran is sparing no effort in solving this mystery and to be honest, we could use a bit of assistance....", sourceObjectiveStatus = "unverified-source-field" }
quests[11575] = { id = 11575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nick of Time", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts. I was surrounded!\n\nA huge magical cube appeared above me. It opened up and pulled me inside. I swear it's true!\n\nJust as it began to close around me, my rescuers swooped in on the backs of drakes - It was amazing! My captors scattered and I was able to escape.\n\nI never thanked them for saving me. Please, {class}, if you see them, pass on my gratitude.", sourceObjective = "Midge in Valiance Keep wants you to go to Amber Ledge to the north and thank those there for rescuing her.", completion = "You can tell your friend that her rescue was our pleasure, as well as our duty.\n\nHer encounter was but a small piece in what I believe to be a large puzzle.\n\nDalaran is sparing no effort in solving this mystery and to be honest, we could use a bit of assistance....", sourceObjectiveStatus = "unverified-source-field" }
quests[11576] = { id = 11576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring the Rift: Cleftcliff Anomaly", description = "Greetings, {race}. I am Garren of Dalaran.\n\nNot long ago, the rift was a peaceful place - geothermally speaking at least.\n\nRecently though, earthquakes have occurred with alarming frequency and scars in the earth have appeared, exposing unique energy fields of chaotic power.\n\nMy mission here is to chart and monitor these anomalies. My instruments indicate that another has appeared on the cliff face to the southwest.\n\nTake this device with you and use it when you locate the new disruption.", sourceObjective = "Garren on Amber Ledge wants you to use the Arcanometer at the Cleftcliff Anomaly.", progress = "Have you taken the readings I requested, {class}?", completion = "Fascinating! This is the largest disruption yet.\n\nThough the worst is yet to come, I fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[11578] = { id = 11578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Chow\" Quest (123)aa COPY", sourceObjective = "Kill Kobold Vermin, 2 of em.", sourceObjectiveStatus = "unverified-source-field" }
quests[11579] = { id = 11579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Chow\" Quest (123)aa COPY", sourceObjective = "Kill Kobold Vermin, 2 of em.", sourceObjectiveStatus = "unverified-source-field" }
quests[11580] = { id = 11580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Horde's Silverpine bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11581] = { id = 11581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Westfall bonfire!", sourceObjectiveStatus = "unverified-source-field" }
quests[11582] = { id = 11582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monitoring the Rift: Sundered Chasm", description = "Did you feel that?! That was just an aftershock... you should've been here a few minutes ago!\n\nI'm afraid I must call upon your services again. My instruments indicate that there is an immense disruption just west of here, far beneath the water's surface.\n\nJust as before, I need you to take the arcanometer and capture the anomaly's data.\n\nI'll cast a spell that will enable you to breathe underwater. If it wears off before you find it, come let me know and I'll renew its effects.", sourceObjective = "Garren at Amber Ledge wants you to use the Arcanometer at the Sundered Chasm anomaly and return to him with the readings.", completion = "It was how big?\n\nThat's impossible! I need to report to Dalaran at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[11583] = { id = 11583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Westfall flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11584] = { id = 11584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", sourceObjective = "Honor the Silverpine Forest flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[11585] = { id = 11585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", sourceObjective = "Speak with Garrosh Hellscream in Warsong Hold.", completion = "A hero of the Horde, eh?\n\n<Garrosh sniffs at the air around you.>\n\nFear...\n\n<Garrosh spits.>\n\nYou won't last long.", sourceObjectiveStatus = "unverified-source-field" }
quests[11586] = { id = 11586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", sourceObjective = "Speak with Garrosh Hellscream in Warsong Hold.", completion = "Do not think that I have forgotten what you did for my people in Nagrand, {name}. Hellscream never forgets.\n\nFor that I am indebted to you and it is why I give you this chance now: run. Leave this place and never look back.\n\nReturn to your home and say a prayer for the dying.", sourceObjectiveStatus = "unverified-source-field" }
quests[11587] = { id = 11587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prison Break", description = "Greetings, {class}. I am Donathan, a loyal representative of Dalaran.\n\nForgive my abruptness, but we find ourselves in the midst of a crisis. Mages all across Azeroth are being abducted and I have been authorized to conscript anyone able to assist in the unraveling of this mystery.\n\nThe camp just south of ours is where our investigation begins. I call upon you to rescue one of the imprisoned mages held there. You must obtain a key from one of the mage hunters and use it to open an arcane prison.", sourceObjective = "Librarian Donathan on Amber Ledge wants you to collect the Beryl Prison Key from one of the Beryl Mage Hunters at Beryl Point and use it to release a trapped mage from an arcane prison.", progress = "I trust you are working diligently to rescue an imprisoned {class}....", completion = "You have done well, {name}.\n\nThe Kirin Tor graciously accept the assistance you have rendered. Know that any service you provide us will not go unrewarded.\n\nPlease, accept this humble offering as a token of Dalaran's appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[11590] = { id = 11590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abduction", description = "{name}, we have a situation.\n\nI've just learned that one of our archmages en route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind her disappearance.\n\nTime is clearly of the essence. We must know what has become of Lady Evanor at once if we are to have any hope of rescuing her.\n\nTake this device. Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should bind him long enough for you to bring him here for questioning.", sourceObjective = "Donathan wants you to use the Arcane Binder on a wounded Beryl Sorcerer at Beryl Point and return to Amber Ledge with him.", progress = "Have you captured a Beryl sorcerer yet, {name}?", completion = "Excellent work, {name}.\n\nWe'll have him prepared for his interrogation at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[11591] = { id = 11591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Steeljaw's Caravan", description = "That dimwitted cur, Steeljaw, tried to take our caravan of supplies on a shortcut through a taunka graveyard!\n\nWe just struck up relations with them!\n\nNow the caravan lies in ruins, overrun by the taunka spirits that rose out of their graves as he was trampling them.\n\nHead south and see if you can salvage the situation, {class}. I sent Grunt Ragefist and a few others down there with him to help out.\n\nWhy don't you see if you can lend a hand.", sourceObjective = "Speak with Grunt Ragefist at Steeljaw's Caravan.", completion = "This isn't good, {class}.\n\nLongrunner Proudhoof says that these are the burial grounds of his honored ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[11592] = { id = 11592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Strike!", description = "One of your orcs named Steeljaw tried to save some time by taking a shortcut through our burial grounds. This had better not be how your Horde normally acts, {race}, or you will find the taunka to be the end of you!\n\nBut, you look as if you want to help fix this situation. Good!\n\nSteeljaw's cursed spirit now haunts this place and disturbs the remains of my ancestors. We must put an end to him!\n\nIf we live through this, tell your Overlord Bor'gorok at the outpost to the north.\n\nAre you with me?", sourceObjective = "Help Longrunner Proudhoof and his Warsong raiders to survive the assault upon Steeljaw's Caravan and finish off the spirit of Force-Commander Steeljaw.\n\nIf successful, report to Overlord Bor'gorok at Bor'gorok Outpost.", completion = "Blood and thunder! You've salvaged our newborn relations with the taunka.\n\nThank you for putting the situation to rights. Aka'Magosh, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11593] = { id = 11593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Honored Dead", description = "Our fallen deserve a hero's funeral, but we cannot bury them here on sacred taunka ground.\n\nI'll not ask you to drag their bodies back here, but take this and head further into the cemetary.  When you come across our dead caravan guards and workers, put them to the torch.\n\nHonor our dead, {class}!", sourceObjective = "Grunt Ragefist at Steeljaw's Caravan has asked you to use Ragefist's Torch to burn any combination of 10 Dead Carvan Guards and Workers.", completion = "Thank you, {class}. We are the Horde, we do not leave our dead behind!\n\nIt should never have been necessary in the first place. Steeljaw was a fool!", sourceObjectiveStatus = "unverified-source-field" }
quests[11594] = { id = 11594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put Them to Rest", description = "Force-Commander Steeljaw's idiocy caused this mess. What was he thinking taking a caravan through a taunka burial mound?\n\nStill, what's done is done. Now it is up to us to deal with the consequences.\n\nOverlord Bor'gorok asked me to help Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest the spirits of his ancestors.\n\nWhat do you say, {class}? Are you <man/strong> enough to handle such a simple task?", sourceObjective = "Put 20 taunka spirits, either Ghostly Sages or Risen Longrunners, to rest and then report back to Grunt Ragefist at Steeljaw's Caravan.", completion = "Well done, {class}! You must have a great deal of experience fighting the undead. And, if you didn't before, you have some now.\n\nYou'll need it if you're going to survive in Northrend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11595] = { id = 11595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Warsong Hold", description = "Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded from your duties because of his temperament, {name}.\n\n<Saurfang nods.>\n\nDid you think that I would forget the name of a hero of Orgrimmar? It is not every day that I have the pleasure of putting the head of Nefarian on a pike!\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", sourceObjective = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "<Overlord Razgor salutes.>\n\nYour reputation precedes you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11596] = { id = 11596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Warsong Hold", description = "Do not let Hellscream dissuade you from your duties as a soldier of the Horde, {race}. He bears a terrible burden in these frozen wastes, with the outcome of his charge resulting in victory over the Scourge or the extinction of all life on Azeroth. It is for this reason that we require your strength and wisdom.\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", sourceObjective = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "Just in time... The Nerubians have seemingly doubled in number in just a week's time. We could use all the help we can get out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[11597] = { id = 11597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Warsong Hold", description = "It seems that we always meet in the direst of circumstances, Scarab Lord. Were you not saving the world from certain destruction the last time we met?\n\n<Saurfang chuckles.>\n\nYour assistance is most welcome in Northrend, despite what the young chieftain might say.\n\nIf we had even a dozen more soldiers with your power, we would be sitting in Orgrimmar right now, hunched over a warm fire.\n\nReport to Overlord Razgor, right outside the main entry to Warsong Hold, to the south.", sourceObjective = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "<Overlord Razgor salutes.>\n\nA living legend battles among us! Your presence alone rouses the spirits of this army!", sourceObjectiveStatus = "unverified-source-field" }
quests[11598] = { id = 11598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Mightstone Quarry", description = "While Warsong is protected by 10 feet of steel and stone on all sides, this quarry is soft and primed for attacks by the Nerubians.\n\n<Razgor points west.>\n\nBeyond this quarry stand thousands of Scourge, awaiting orders to attack. Should the Nerubians take down our inner defenses, we will be overrun by the undead legions of Arthas.\n\nWe can't let that happen - which is why you're going on the offensive and slaughtering the Nerubians in the quarry.\n\nBlood and thunder, soldier! Take 'em both with you.", sourceObjective = "Overlord Razgor at Warsong Hold wants you to kill 15 Nerub'ar Nerubians.", completion = "You've slowed them down, but more are sure to join the fight. Were you able to locate any of their egg sacs while in the quarry?", sourceObjectiveStatus = "unverified-source-field" }
quests[11599] = { id = 11599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thassarian, My Brother", description = "I recently received word from William Allerton, a family friend, that my brother enlisted here in Valiance Keep on the same day he did.  Thing is... my brother's been dead for years.\n\nI sold everything I owned to come looking for Thassarian, only to be stonewalled by the local bureaucracy.  I've even been threatened with arrest if I keep snooping around.\n\nI need someone in the good graces of the higher-ups... someone like you.  If you can help me, I heard that William's stationed at the Farshire mine.", sourceObjective = "Look for William Allerton inside the Farshire mine.", completion = "The corpse matches the description that Leryssa gave you of William Allerton.  Oddly enough, there are no bite or claw marks on him.", sourceObjectiveStatus = "unverified-source-field" }
quests[11600] = { id = 11600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Late William Allerton", description = "William's neck has been cut by a sharp object.\n\nFurther inspection reveals a single clue to bring to Leryssa - an enlistment card bearing the name of William Allerton.", sourceObjective = "Bring the Enlistment Card to Leryssa at Valiance Keep in Borean Tundra.", progress = "You spoke to William, {name}?", completion = "Do you think William's death was a random killing by the Scourge?  Things sure seem fishy.\n\nSomething's up.  We must find Thassarian.", sourceObjectiveStatus = "unverified-source-field" }
quests[11601] = { id = 11601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost and Found", description = "Poor Mr. Allerton might yet help us find my brother.\n\n<Leryssa unveils a voluminous book, not unlike an army recruitment ledger.>\n\nI borrowed it, ok?  Let's see, does that enlistment card have a date?\n\nWilliam saw Thassarian at the enlistment line.  Their entries must be near each other... here it is!\n\nHe was assigned to... Unit S?  All the other military units are named after Alliance towns.\n\nWho's in the unit?  Where are they deployed?  We need rumors.  See if the innkeeper's heard anything.", sourceObjective = "Speak to James Deacon at the inn in Valiance Keep.", completion = "Can't say I can help you friend.  But I might know someone who can.", sourceObjectiveStatus = "unverified-source-field" }
quests[11602] = { id = 11602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Off the Source", description = "Aerial reconnaissance of the quarry reports that the Nerubians are storing their eggs on the scaffolding surrounding the base. Smart beasts these are... They're keeping the eggs high and dry, away from the epicenter of conflict.\n\nYou're going to have to go back out there and track down their eggs. Find 'em, smash 'em, and trash 'em.\n\nEach egg destroyed means twenty less Nerubians feeding on our corpses.", sourceObjective = "Overlord Razgor at Warsong Hold wants you to destroy 10 Nerub'ar Egg Sacs.", completion = "They just keep on coming, despite our best efforts. Something's gotta give, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11603] = { id = 11603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Wine, Truth", description = "The military was all that old man Colburn had.  After he retired, he still clung to it like a lifeline.\n\nHe knows the name of every general, unit, brigade, detachment... you name it.  He's the man you need.\n\nProblem is, his mind is scarred.  He won't talk to anyone unless he gets his Kul Tiras wine.  Takes him back to the times he was a marine.\n\nI haven't received a shipment in months.  The last merchant ship out of Kul Tiras sunk northeast of here.  See if you can salvage a bottle to bring Colburn.", sourceObjective = "Salvage a bottle of Kul Tiras Wine from the underwater shipwreck northeast of Valiance Keep and bring it to Old Man Colburn in the Valiance Keep inn.", progress = "<The old man looks up at you with a blank look on his face.>", completion = "Mmmmm... not too bitter... not too dry... it's just like the old days, with the lads at the barracks.", sourceObjectiveStatus = "unverified-source-field" }
quests[11604] = { id = 11604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deserter", description = "Unit S... Unit S.... hmmmpph.... don't make any sense... it oughta be named after a town...\n\nDarkshire was sent to Dragonblight.  The Goldshire boys were sent to the Fjord.   Where did I hear...\n\nOh, yes... the deserter!  There's a turn-tail in the barracks prison.  Got thrown in not too long ago.  Kept saying that \"S\" stood for suicide.\n\nLook for the deserter.  He might have some information for you.", sourceObjective = "Find the prison inside Inner Hold in Valiance Keep and speak to the deserter.", completion = "Whad'ya want?  I have enough problems as it is!", sourceObjectiveStatus = "unverified-source-field" }
quests[11605] = { id = 11605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Honored Ancestors", description = "<A distant voice echoes in your head as you regard the stone statue.>\n\nDo not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr people, a skilled craftsman in my own time and the guardian of this quarry for centuries.\n\nThe quarry has been overrun, leaving many statues unfinished while the ancestors' spirits wander the world. Will you aid me in righting this wrong?\n\nFirst, I must know the names of these wandering ancestors. Look for the markers near their statues.", sourceObjective = "Elder Atkanok outside Coldrock Quarry wants you to identify the statues of Elder Kesuk, Elder Sagani, and Elder Takret.", progress = "<The distant voice returns.>\n\nHave you recovered the names of the wandering elders?", completion = "<Elder Atkanok's voice greets you as you approach his statue.>\n\nWell done, {name}. With the names of the wandering elders, we can continue the ceremonies disrupted during the attack. However, before the elders' spirits can be led to their stones, we must calm the spirits of the murdered craftsmen and shaman. Otherwise, the ancestor spirits may never hear the ceremony's call.", sourceObjectiveStatus = "unverified-source-field" }
quests[11606] = { id = 11606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patience is a Virtue that We Don't Need", description = "We can kill all the Nerubians that we see and destroy all the eggs that we find, but those things won't stop coming until we blow their tunnels and passageways up. Of course, we can't do that without some heavy grade munitions. Unfortunately, most of our stockpile is being used up by the goblins and blacksmiths for our siege tanks and weaponry.\n\nWe do happen to have a pretty good supply of the stuff out in Mightstone Quarry - underneath all the Nerubian crap. You'll just have to go out and get it for me.", sourceObjective = "Quartermaster Holgoth at Warsong Hold wants you to recover 15 crates of Warsong Munitions.", progress = "We're running out of time here, {class}.", completion = "If my calculations are correct - and they're often not - you're gonna need about 10-20 seaforium depth charges.\n\nOh yea, you'll be planting these mothers into their sinkholes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11607] = { id = 11607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Spirits", description = "In the attack on the quarry, the shaman and craftsmen working here were slain. The violence threw the spirit world into utter chaos and we'll be unable to guide the ancestors home unless we find a way to soothe the spirits of the murdered.\n\nThe aggressors themselves pay no heed to the spirits, but their companions, the beryl hounds, sense the spirits and hold them in thrall.\n\nKill the beryl hounds, and using the raw energy left behind, break the imprisonment of the spirits of the innocent.", sourceObjective = "Elder Atkanok, on the outskirts of Coldrock Quarry, wants you to free the spirits of 3 Kaskala Craftsmen and 3 Kaskala Shaman.", progress = "How fare the spirits of the innocent?", completion = "I can sense the upheaval in the spirit world beginning to calm. You have done well, {name}. The spirits of the ancestors are fortunate to have your help in this time of need.", sourceObjectiveStatus = "unverified-source-field" }
quests[11608] = { id = 11608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bury Those Cockroaches!", description = "North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub'ar sinkholes.\n\n<Holgoth hands you a bundle.>\n\nBe very careful with that package, {name}. Mishandle it and you'll be dog meat.\n\nInside the bundle are seaforium depth charges. Get to each of those Nerub'ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse.\n\nGet a move on!", sourceObjective = "Quartermaster Holgoth at Warsong Hold wants you to use the Seaforium Depth Charge Bundle to destroy the Nerub'ar sinkholes to the south, east, west and north of Warsong Hold.", progress = "Well?", completion = "That'll stop 'em - at least I think it'll stop 'em. Either way, you've done your part. That's all an orc can ask for, no?", sourceObjectiveStatus = "unverified-source-field" }
quests[11609] = { id = 11609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Up the Pieces", description = "With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items.\n\nThere is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, {name}, for some are centuries old. You may need to wrest them from the hands of the invaders.", sourceObjective = "Bring 6 Tuskarr Ritual Objects to Elder Atkanok, who stands outside Coldrock Quarry.", progress = "Have you recovered a full set of ritual items?", completion = "<You hold the objects before the statue of Elder Atkanok.>\n\nThose will suffice, although they are in a sad state. Some of them have survived centuries of use, only to be battered and stolen by barbarians.", sourceObjectiveStatus = "unverified-source-field" }
quests[11610] = { id = 11610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leading the Ancestors Home", description = "With your help, the ancestor spirits can now be guided to their rightful homes, the statues lovingly prepared by Kaskala's craftsmen and shaman.\n\nThe ceremonies for these ancestors were interrupted during the attack on the quarry, and you will need to complete them. Take with you the objects that you recovered from the quarry, stand in front of the statues with the name markers, and recite this chant.\n\n<Words in a strange language flood your head, but you have no difficulty recalling them.>", sourceObjective = "Elder Atkanok wants you to guide the spirits of Elder Kesuk, Elder Sagani, and Elder Takret to their stone monuments.", progress = "Have you completed the ceremonies for the ancestors?", completion = "The ancestors have found their statues, and they have you to thank, {name}. The craftsmen of Kaskala will return to the quarry and ensure that the line of ancestors continues unbroken. For our part, the ancestors will continue to observe you with interest, as it seems your path is just beginning.", sourceObjectiveStatus = "unverified-source-field" }
quests[11611] = { id = 11611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taken by the Scourge", description = "<Mortuus sighs.>\n\nPeons... We may as well post up a sign offering the Nerub'ar a free meal.\n\nSee, the problem with a peon is that: (1) they're dumber than dirt; and (2) they're weaker than a leper gnome. Of course they're the first to be taken by the Scourge!\n\nThis puts me in a bit of a predicament, you see. Without peons, manual labor comes to a halt. No peons, no construction.\n\nFind and release my peons, {race}. If they're alive, you'll find 'em spun up in webbing throughout Mightstone Quarry.", sourceObjective = "Foreman Mortuus at Warsong Hold wants you to free 5 Warsong Peons.", progress = "No peons, no buildings. And no, we're not going to replace them with goblins. Too damned expensive...", completion = "Most of them made it back. The ones smart enough to know that we're inside the gigantic metal and stone building, anyway...\n\nRegardless, a job well done. I hear you sprung more than a couple peons loose.\n\nOh yes, you're the talk of the... um... fortress.", sourceObjectiveStatus = "unverified-source-field" }
quests[11612] = { id = 11612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming the Quarry", description = "You're a welcome sight, {class}. My name is Etaruk, and I used to be a craftsman here at the Coldrock Quarry.\n\nMy companions and I were preparing a new set of statues for their last set of rites when we saw those mysterious blue platforms come flying over the plateau.\n\nWhen they landed, the mages they carried swarmed the quarry, murdering my fellows and plundering the quarry. If we don't stop them, they'll destroy our statues and make off with our artifacts. Will you help me defeat the invaders?", sourceObjective = "Etaruk, camped near the entrance to the Coldrock Quarry, wants you to kill 12 Beryl Treasure Hunters.", progress = "Have you started ridding the quarry of our enemies?", completion = "Now that these strange mages know that the people of Kaskala and their allies will not give up the quarry so easily, we must maintain our efforts and defeat them completely.\n\nMy brothers in Kaskala have also come under attack and will not be able to support us, but with your help, {name}, we can overcome these pillagers.", sourceObjectiveStatus = "unverified-source-field" }
quests[11613] = { id = 11613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karuk's Oath", description = "They call themselves the Kvaldir.  My people have legends about them; we call them the tuk-hariq - walkers of the fog.\n\nMy village was destroyed by these giant mist-men.  Everyone I knew was slain, including my father Ariut.\n\nBy tuskarr law I must seek retribution against those who shed my kin's blood.\n\nI am but a fisherman and I've not yet passed the test of manhood... I cannot stand toe-to-toe with the vile Kvaldir.\n\nIf you were to carry out my blood duty for me, I will be in great debt to you.", sourceObjective = "Karuk wants you to slay 6 Skadir Raiders and 5 Skadir Longboatsmen.", progress = "Did you succeed, {race}?  The Kvaldir are cruel warriors.  Do not expect any quarter from them.", completion = "You've done my people a great favor, {name}.  I must ask one more thing of you, however.", sourceObjectiveStatus = "unverified-source-field" }
quests[11614] = { id = 11614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untold Truths", description = "We are here by order of Varimathras! The mission of the Shadowstalkers is a simple one: spy. Well, spy with a little assassination on the side.\n\nOne of my best field agents has gone missing. I haven't heard from him in days, which has left me fearing the worst. No, not death! Death would be ideal. I fear he may have gone rogue... turned traitor even.\n\nHis last known location was northern Mightstone Quarry. He was gathering intelligence on the Nerubians. Find him.\n\nHe better be dead...", sourceObjective = "Find Shadowstalker Luther in Mightstone Quarry.", completion = "It doesn't get much deader than this... Strangely, the Nerubians did not devour the corpse.\n\nAfter careful examination you see that Luther's death was self inflicted - deadly poison. Smart. Nerubians won't come near this toxic corpse.\n\nYou notice that Luther is holding a journal.", sourceObjectiveStatus = "unverified-source-field" }
quests[11615] = { id = 11615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerub'ar Secrets", description = "You skim through the pages of the book, looking for anything of importance. On the last page you discover what appears to be frantic scribbling:\n\nNecrolords. At least a dozen by my count.\n\nFarms to west being used as some sort of horrible spawning glade for Scourge.\n\nRow upon row of victims.\n\nI think they're on to me. Made a dash for the hold. I won't be captured alive.\n\nDreadvenom hemotoxin. If they decide to bite into me, they'll be in for a surprise.\n\nTake this information back to Barthus.", sourceObjective = "Take Luther's Journal to Shadowstalker Barthus at Warsong Hold.", progress = "Is he dead?", completion = "<Barthus flips to the last page of the journal and begins reading.>\n\nThis is very bad news. Hellscream must be notified at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[11616] = { id = 11616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Hellscream", description = "<Barthus tears out the last page and rolls it up.>\n\nTake this to Hellscream at once! In the meantime, I'm going to send a team to scout out the farms.\n\nBe sure to tell Hellscream that we're going to need reinforcements.", sourceObjective = "Take Barthus's Note to Garrosh Hellscream at Warsong Hold.", progress = "What is the meaning of this interruption? Do not burden me with nonsense!", completion = "<Hellscream reads the journal entry.>\n\nIs that all?", sourceObjectiveStatus = "unverified-source-field" }
quests[11617] = { id = 11617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hampering Their Escape", description = "I'm sure you've seen those blue and white platforms hovering over the quarry. They're the transportation the mage hunters used to land their forces here, and now they're loading them up with our artifacts and fragments of our statues.\n\nWe must stop them before they leave the quarry.\n\nThe small creatures digging in the quarry carry explosives. Take them and use them to destroy the three floating platforms. The leader keeps watch from a fourth, grounded platform, but we'll deal with him afterward.", sourceObjective = "Etaruk, outside the Coldrock Quarry, wants you to destroy the North Platform, the East Platform, and the West Platform.", progress = "Have you succeeded in destroying the mage hunters' flying platforms?", completion = "The mage hunters won't find it as easy to plunder our quarry and steal our artifacts as they'd imagined. With your help, we'll win back the quarry and set things right again.", sourceObjectiveStatus = "unverified-source-field" }
quests[11618] = { id = 11618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements Incoming...", description = "<Hellscream shakes his head.>\n\nYou may not have noticed that we're trying to win a war here, {race}. I need all available soldiers at the primary points of conflict. This means that we don't have any real soldiers to spare for these minor incursions.\n\n<Hellscream pauses to think.>\n\nIf Barthus wants reinforcements at the farm...\n\n<Hellscream claps his hands together.>\n\n...he shall have them! Report to Barthus's assassins at the farms, west of here. Let them know that reinforcements have arrived.", sourceObjective = "Seek out Shadowstalker Ickoris at the Warsong Farms Outpost west of Warsong Hold.", completion = "This is it? Hellscream sent a single {race} boy?\n\nIf I still had a jaw it would be on the floor right now.", sourceObjectiveStatus = "unverified-source-field" }
quests[11619] = { id = 11619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamel the Cruel", description = "My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach.\n\nYou've dealt with his men already.  Finish what you've started, {name}.  Avenge my father and I will share with you what little I still have.", sourceObjective = "Karuk wants you to defeat Gamel the Cruel at Riplash Strand.", progress = "Did you defeat Gamel, {class}?", completion = "You did it, {name}!  The spirits of the slain tuskarr can now rest in peace - their deaths have been avenged!", sourceObjectiveStatus = "unverified-source-field" }
quests[11620] = { id = 11620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Father's Words", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the Kvaldir have kept a naga priestess alive at the temple on the west side of the shore.\n\nShe will no doubt have great reason to resent her uninvited Kvaldir guests.  Perhaps my father is expecting her to cooperate with you in some way.", sourceObjective = "Look for Veehja at the Shrine of Scales on Riplash Strand.", completion = "Hsssssssssssss!  Have you come to mock me, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11621] = { id = 11621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tablet of Leviroth", description = "You scour through the tablet's etchings, looking for any text you can understand.  You finally find the following fragment:\n\n\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters.  His emissary will then awake.\"\n\nKaruk might be interested in this information.", sourceObjective = "Return to Karuk with the information you found on the tablet.You scour through the tablet's etchings, looking for any text you can understand. You finally find the following fragment:\n\n\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters. His emissary will then awake.\"\n\nKaruk might be interested in this information.", sourceObjectiveStatus = "unverified-source-field" }
